import React, { useEffect, useRef } from 'react';

interface SectionVisualizerProps {
    mode: 'search' | 'redaction' | 'logic' | 'core' | 'shield' | 'swarm' | 'predictive' | 'translation' | 'identity';
    color: string;
}

export const SectionVisualizer: React.FC<SectionVisualizerProps> = ({ mode, color }) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const containerRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        const canvas = canvasRef.current;
        const container = containerRef.current;
        if (!canvas || !container) return;

        const ctx = canvas.getContext('2d', { alpha: true });
        if (!ctx) return;

        let frameId: number;
        let time = 0;

        // --- HELPER: Polyfill for roundRect ---
        const drawRoundedRect = (x: number, y: number, w: number, h: number, r: number) => {
            if (ctx.roundRect) {
                ctx.beginPath();
                ctx.roundRect(x, y, w, h, r);
                return;
            }
            // Fallback for browsers without roundRect
            ctx.beginPath();
            ctx.moveTo(x + r, y);
            ctx.lineTo(x + w - r, y);
            ctx.quadraticCurveTo(x + w, y, x + w, y + r);
            ctx.lineTo(x + w, y + h - r);
            ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
            ctx.lineTo(x + r, y + h);
            ctx.quadraticCurveTo(x, y + h, x, y + h - r);
            ctx.lineTo(x, y + r);
            ctx.quadraticCurveTo(x, y, x + r, y);
            ctx.closePath();
        };

        // --- STATE MANAGEMENT ---
        const state: any = {
            width: 0,
            height: 0,
            particles: [],
            nodes: [],
            links: [], 
            grid: [],
            columns: [], 
            task: null, 
            agent: { state: 'idle', t: 0, heldBox: null, armHeight: 0, armExt: 0 },
            boxes: [], 
            stack: [],
            // Identity Mode (Learning Feed) State
            feedState: 'reading', // reading -> selecting -> feedback -> swiping
            feedTimer: 0,
            currentCardIndex: 0,
            swipeOffset: 0,
            streak: 12,
            xp: 850,
            cursor: { x: 0, y: 0, targetX: 0, targetY: 0, clicking: false },
            feedCards: [
                { 
                    type: 'CYBER_SECURITY', 
                    bg: ['#1e1b4b', '#312e81'], // Indigo
                    author: "@SecurOps",
                    q: "Suspicious Email Detected", 
                    sub: "Sender domain is 'goggle.com'. What's the protocol?", 
                    opts: ["Report & Delete", "Reply to Verify"], 
                    correct: 0, 
                    likes: "12.4k" 
                },
                { 
                    type: 'SAFETY_PROTO', 
                    bg: ['#451a03', '#78350f'], // Amber
                    author: "@PlantManager",
                    q: "Forklift in Zone B", 
                    sub: "Pedestrian light is flashing red.", 
                    opts: ["Right of Way", "Stop & Wait"], 
                    correct: 1, 
                    likes: "8.2k" 
                },
                { 
                    type: 'DATA_PRIVACY', 
                    bg: ['#022c22', '#115e59'], // Emerald
                    author: "@ComplianceBot",
                    q: "PII in Comments?", 
                    sub: "Customer put SSN in 'Notes' field.", 
                    opts: ["Ignore", "Redact Immediately"], 
                    correct: 1, 
                    likes: "45k" 
                },
                { 
                    type: 'HR_POLICY', 
                    bg: ['#4c0519', '#9f1239'], // Rose
                    author: "@PeopleTeam",
                    q: "Gift Policy", 
                    sub: "Vendor offers $200 tickets.", 
                    opts: ["Decline", "Accept"], 
                    correct: 0, 
                    likes: "2.1k" 
                }
            ],
            // Logic/Strategy Mode State
            packets: [],
            initializedMode: null
        };

        const init = (w: number, h: number) => {
            state.particles = [];
            state.nodes = [];
            state.links = [];
            state.grid = [];
            state.columns = [];
            state.task = null;
            state.boxes = [];
            state.stack = [];
            state.packets = [];
            state.agent = { state: 'idle', t: 0, heldBox: null, armHeight: 0, armExt: 0 };

            // Identity specific
            state.feedState = 'reading';
            state.feedTimer = 0;
            state.currentCardIndex = 0;
            state.swipeOffset = 0;
            state.streak = 12;
            state.cursor = { x: w/2, y: h*0.8, targetX: w/2, targetY: h*0.8, clicking: false };

            state.initializedMode = mode;

            if (mode === 'search') {
                const particleCount = 80;
                for(let i=0; i<particleCount; i++) {
                    state.particles.push({
                        x: Math.random() * w,
                        y: Math.random() * h,
                        vx: 2 + Math.random() * 1.5,
                        vy: (Math.random() - 0.5) * 0.5,
                        targetLane: Math.floor(Math.random() * 5),
                        size: 0.5 + Math.random() * 0.5
                    });
                }
            }
            else if (mode === 'logic') {
                // STRATEGY BUILDER
                state.nodes.push({ id: 0, x: w * 0.15, y: h * 0.3, label: "DEMAND SPIKE", type: 'trigger', active: 0 });
                state.nodes.push({ id: 1, x: w * 0.15, y: h * 0.7, label: "INVENTORY LOW", type: 'trigger', active: 0 });
                state.nodes.push({ id: 2, x: w * 0.45, y: h * 0.5, label: "ALLOCATION LOGIC", type: 'process', active: 0 });
                state.nodes.push({ id: 3, x: w * 0.75, y: h * 0.25, label: "PRIORITY: RETAIL", type: 'action', active: 0 });
                state.nodes.push({ id: 4, x: w * 0.75, y: h * 0.75, label: "LIMIT WHOLESALE", type: 'action', active: 0 });
                state.links.push({ from: 0, to: 2 });
                state.links.push({ from: 1, to: 2 });
                state.links.push({ from: 2, to: 3 });
                state.links.push({ from: 2, to: 4 });
            }
            else if (mode === 'core') {
                // KNOWLEDGE TREE - Initialize here to avoid render-loop race conditions
                // Root
                state.nodes.push({id:0, x: 0, y: 0, layer: 0});

                // Layers
                const layerCounts = [6, 12, 18];
                let idCounter = 1;

                // Create nodes first
                // Layer 1
                for(let i=0; i<layerCounts[0]; i++) {
                    const angle = (i / layerCounts[0]) * Math.PI * 2;
                    state.nodes.push({
                        id: idCounter++,
                        x: Math.cos(angle) * 60,
                        y: Math.sin(angle) * 60,
                        layer: 1
                    });
                }
                // Layer 2
                for(let i=0; i<layerCounts[1]; i++) {
                    const angle = (i / layerCounts[1]) * Math.PI * 2 + 0.2;
                    state.nodes.push({
                        id: idCounter++,
                        x: Math.cos(angle) * 120,
                        y: Math.sin(angle) * 120,
                        layer: 2
                    });
                }

                // Links
                // Root to Layer 1
                for(let i=1; i<=layerCounts[0]; i++) {
                    state.links.push({from: 0, to: i});
                }
                // Layer 1 to Layer 2 (Simple fan out)
                for(let i=0; i<layerCounts[1]; i++) {
                    const targetNodeId = 1 + layerCounts[0] + i; // Start after layer 1
                    const sourceNodeId = 1 + Math.floor(i / 2); // Connect 2 outer to 1 inner
                    if(state.nodes[targetNodeId] && state.nodes[sourceNodeId]) {
                        state.links.push({from: sourceNodeId, to: targetNodeId});
                    }
                }
            }
        };

        const resize = () => {
            const rect = container.getBoundingClientRect();
            if (rect.width === 0 || rect.height === 0) return;

            const dpr = window.devicePixelRatio || 1;

            canvas.width = rect.width * dpr;
            canvas.height = rect.height * dpr;

            canvas.style.width = `${rect.width}px`;
            canvas.style.height = `${rect.height}px`;

            ctx.scale(dpr, dpr);

            state.width = rect.width;
            state.height = rect.height;

            // Re-init if dimensions change significantly or mode changed
            if (mode !== state.initializedMode || Math.abs(state.width - rect.width) > 10) {
                init(rect.width, rect.height);
            }
        };

        const render = () => {
            time += 0.01;
            const w = state.width;
            const h = state.height;
            const cx = w/2;
            const cy = h/2;

            ctx.clearRect(0, 0, w, h);

            if (mode === 'identity') {
                // --- "SkillStream": TikTok-style Corporate Learning Feed ---

                // 1. UPDATE STATE & PHYSICS
                state.feedTimer++;
                const card = state.feedCards[state.currentCardIndex];

                // -- Cursor Simulation Logic --
                if (state.feedState === 'reading') {
                    // Hover around a bit
                    state.cursor.targetX = w/2 + Math.sin(time) * 20;
                    state.cursor.targetY = h * 0.75 + Math.cos(time * 1.5) * 20;

                    if (state.feedTimer > 120) { // Wait 2s before acting
                        state.feedState = 'selecting';
                    }
                } 
                else if (state.feedState === 'selecting') {
                    // Move to correct button
                    const btnH = 50;
                    const spacing = 15;
                    const btnY = h * 0.65 + card.correct * (btnH + spacing) + btnH/2;

                    state.cursor.targetX = w/2;
                    state.cursor.targetY = btnY;

                    // Snap click when close
                    const dx = state.cursor.targetX - state.cursor.x;
                    const dy = state.cursor.targetY - state.cursor.y;
                    if (Math.sqrt(dx*dx + dy*dy) < 5) {
                        state.cursor.clicking = true;
                        state.feedState = 'feedback';
                        state.feedTimer = 0;
                        state.streak++;
                        state.xp += 150;

                        // Explosion
                        for(let i=0; i<40; i++) {
                            state.particles.push({
                                x: state.cursor.x,
                                y: state.cursor.y,
                                vx: (Math.random()-0.5) * 15,
                                vy: (Math.random()-0.5) * 15 - 5,
                                life: 1.0,
                                color: ['#4ade80', '#fbbf24', '#ffffff'][Math.floor(Math.random()*3)]
                            });
                        }
                    }
                }
                else if (state.feedState === 'feedback') {
                    state.cursor.clicking = false;
                    if (state.feedTimer > 80) { // Wait 1.5s viewing success
                        state.feedState = 'swiping';
                        state.cursor.targetY = h * 0.2; // Move up to swipe
                        state.feedTimer = 0;
                    }
                }
                else if (state.feedState === 'swiping') {
                    // Lerp Offset
                    state.swipeOffset += (-h - state.swipeOffset) * 0.15;

                    // Reset
                    if (Math.abs(state.swipeOffset + h) < 5) {
                        state.currentCardIndex = (state.currentCardIndex + 1) % state.feedCards.length;
                        state.swipeOffset = 0;
                        state.feedState = 'reading';
                        state.feedTimer = 0;
                        state.cursor.y = h + 100; // Reset cursor pos
                    }
                }

                // Cursor Physics
                state.cursor.x += (state.cursor.targetX - state.cursor.x) * 0.15;
                state.cursor.y += (state.cursor.targetY - state.cursor.y) * 0.15;

                // -- RENDER --

                ctx.save();
                ctx.translate(0, state.swipeOffset);

                // 1. Dynamic Video Background
                const grad = ctx.createLinearGradient(0, 0, 0, h);
                grad.addColorStop(0, card.bg[0]);
                grad.addColorStop(1, card.bg[1]);
                ctx.fillStyle = grad;
                ctx.fillRect(0, 0, w, h);

                // Animated BG Elements (Subtle movement)
                ctx.save();
                ctx.globalAlpha = 0.1;
                ctx.fillStyle = '#fff';
                for(let i=0; i<5; i++) {
                    const bx = (time * 20 + i * 50) % w;
                    const by = (Math.sin(time + i) * 100 + h/2);
                    ctx.beginPath(); ctx.arc(bx, by, 50 + i*20, 0, Math.PI*2); ctx.fill();
                }
                ctx.restore();

                // 2. Right Sidebar (TikTok style actions)
                const rightMargin = w - 40;
                const bottomMargin = h - 100;

                // Avatar
                ctx.beginPath(); ctx.arc(rightMargin, bottomMargin - 150, 20, 0, Math.PI*2); 
                ctx.fillStyle = '#fff'; ctx.fill();
                ctx.lineWidth = 2; ctx.strokeStyle = '#ef4444'; ctx.stroke();
                // Plus icon
                ctx.fillStyle = '#ef4444'; ctx.beginPath(); ctx.arc(rightMargin, bottomMargin - 135, 8, 0, Math.PI*2); ctx.fill();

                // Heart
                ctx.fillStyle = state.feedState === 'feedback' || state.feedState === 'swiping' ? '#ef4444' : 'rgba(255,255,255,0.8)';
                ctx.font = '24px serif'; ctx.textAlign='center'; ctx.fillText('♥', rightMargin, bottomMargin - 90);
                ctx.font = '10px sans-serif'; ctx.fillStyle='#fff'; ctx.fillText(card.likes, rightMargin, bottomMargin - 75);

                // Share
                ctx.fillStyle = 'rgba(255,255,255,0.8)';
                ctx.font = '24px serif'; ctx.fillText('➤', rightMargin, bottomMargin - 30);
                ctx.font = '10px sans-serif'; ctx.fillStyle='#fff'; ctx.fillText("Share", rightMargin, bottomMargin - 15);

                // 3. Bottom Content Overlay
                ctx.textAlign = 'left';

                // Author
                ctx.font = 'bold 12px sans-serif'; ctx.fillStyle = '#fff';
                ctx.fillText(card.author, 20, h * 0.45);

                // Question (The Caption)
                ctx.font = 'bold 18px sans-serif'; 
                const lines = card.q.split(' '); 
                ctx.fillText(card.q, 20, h * 0.45 + 25);

                // Subtext
                ctx.font = '12px sans-serif'; ctx.fillStyle = 'rgba(255,255,255,0.8)';
                ctx.fillText(card.sub, 20, h * 0.45 + 45);

                // 4. Interactive Quiz Buttons
                card.opts.forEach((opt: string, i: number) => {
                    const btnH = 50;
                    const spacing = 15;
                    const btnW = w * 0.75;
                    const btnX = (w - btnW) / 2;
                    const btnY = h * 0.65 + i * (btnH + spacing);

                    const isCorrect = i === card.correct;
                    const isSelected = (state.feedState === 'feedback' || state.feedState === 'swiping') && isCorrect;

                    // Glassmorphism Button
                    ctx.fillStyle = isSelected ? '#22c55e' : 'rgba(255,255,255,0.15)';
                    if (isSelected) {
                        ctx.shadowColor = '#22c55e'; ctx.shadowBlur = 20;
                    } else {
                        ctx.shadowColor = 'transparent'; ctx.shadowBlur = 0;
                    }

                    // Use polyfill
                    drawRoundedRect(btnX, btnY, btnW, btnH, 12);
                    ctx.fill();

                    // Text
                    ctx.fillStyle = '#fff'; ctx.font = 'bold 13px sans-serif'; ctx.textAlign = 'center';
                    ctx.fillText(opt, w/2, btnY + 30);

                    // Reset Shadow
                    ctx.shadowBlur = 0;
                });

                // 5. Feedback Banner (Duolingo Style)
                if (state.feedState === 'feedback' || state.feedState === 'swiping') {
                    const bannerY = state.feedState === 'feedback' ? 
                        h - 80 - Math.min(1, state.feedTimer/10) * 20 : // Pop up
                        h - 100 + state.feedTimer; // Slide down

                    ctx.fillStyle = '#22c55e';
                    ctx.fillRect(0, bannerY, w, 150);

                    ctx.fillStyle = '#fff';
                    ctx.font = 'bold 20px sans-serif'; ctx.textAlign = 'left';
                    ctx.fillText("Nice job!", 20, bannerY + 40);
                    ctx.font = '12px sans-serif';
                    ctx.fillText(`Streak: ${state.streak} days 🔥`, 20, bannerY + 60);
                }

                // 6. Particles
                for (let i = state.particles.length - 1; i >= 0; i--) {
                    const p = state.particles[i];
                    p.x += p.vx;
                    p.y += p.vy;
                    p.vy += 0.8; // Gravity
                    p.life -= 0.02;

                    if (p.life <= 0) {
                        state.particles.splice(i, 1);
                        continue;
                    }

                    ctx.fillStyle = p.color;
                    ctx.globalAlpha = p.life;
                    ctx.fillRect(p.x, p.y, 6, 6); // Confetti squares
                }
                ctx.globalAlpha = 1;

                // 7. Top Header (Progress)
                ctx.fillStyle = 'rgba(0,0,0,0.2)';
                ctx.fillRect(0, 0, w, 60);

                // Progress bar
                ctx.fillStyle = 'rgba(255,255,255,0.2)';
                ctx.fillRect(20, 20, w-40, 4);
                ctx.fillStyle = '#fff';
                // Simulated progress
                const prog = ((state.currentCardIndex + 1) / state.feedCards.length) * (w-40);
                ctx.fillRect(20, 20, prog, 4);

                ctx.restore(); // End Swipe Transform

                // 8. Simulated Cursor
                if (state.feedState !== 'swiping') {
                    ctx.shadowBlur = 10; ctx.shadowColor = 'rgba(0,0,0,0.5)';
                    ctx.fillStyle = '#fff';
                    // Pointer shape
                    ctx.beginPath();
                    ctx.moveTo(state.cursor.x, state.cursor.y);
                    ctx.lineTo(state.cursor.x + 12, state.cursor.y + 12);
                    ctx.lineTo(state.cursor.x + 5, state.cursor.y + 12);
                    ctx.lineTo(state.cursor.x, state.cursor.y + 18);
                    ctx.closePath();
                    ctx.fill();

                    // Click Ripple
                    if (state.cursor.clicking) {
                        ctx.strokeStyle = 'rgba(255,255,255,0.8)';
                        ctx.lineWidth = 2;
                        ctx.beginPath(); ctx.arc(state.cursor.x, state.cursor.y, 20, 0, Math.PI*2); ctx.stroke();
                    }
                    ctx.shadowBlur = 0;
                }
            }
            else if (mode === 'search') {
                const processLine = w * 0.4;
                const laneCount = 5;
                const laneHeight = h / laneCount;

                ctx.lineWidth = 1;
                ctx.strokeStyle = 'rgba(255, 255, 255, 0.08)';
                for(let i=0; i<laneCount; i++) {
                    const ly = i * laneHeight + laneHeight/2;
                    ctx.beginPath(); ctx.moveTo(processLine, ly); ctx.lineTo(w, ly); ctx.stroke();
                }

                const scannerGlow = ctx.createLinearGradient(processLine, 0, processLine + 60, 0);
                scannerGlow.addColorStop(0, color);
                scannerGlow.addColorStop(1, 'transparent');
                ctx.fillStyle = scannerGlow;
                ctx.globalAlpha = 0.15;
                ctx.fillRect(processLine, 0, 60, h);

                ctx.fillStyle = color;
                ctx.globalAlpha = 0.8;
                ctx.fillRect(processLine, 0, 2, h);

                state.particles.forEach((p: any) => {
                    p.x += p.vx;
                    if (p.x < processLine) {
                        p.y += p.vy;
                        if (p.y < 0) p.y += h;
                        if (p.y > h) p.y -= h;
                        ctx.fillStyle = 'rgba(255, 255, 255, 0.4)';
                        ctx.globalAlpha = 0.6;
                        ctx.beginPath(); ctx.arc(p.x, p.y, p.size * 2, 0, Math.PI*2); ctx.fill();
                    } else {
                        const targetY = p.targetLane * laneHeight + laneHeight/2;
                        p.y += (targetY - p.y) * 0.15; 
                        p.x += 1.5; 
                        ctx.fillStyle = color;
                        ctx.globalAlpha = 1;
                        const packetWidth = 20 * p.size;
                        const packetHeight = 4;
                        ctx.shadowColor = color; ctx.shadowBlur = 10;
                        ctx.fillRect(p.x, p.y - packetHeight/2, packetWidth, packetHeight);
                        ctx.shadowBlur = 0;
                    }
                    if (p.x > w + 50) {
                        p.x = -20;
                        p.y = Math.random() * h;
                        p.vx = 2 + Math.random() * 1.5;
                        p.targetLane = Math.floor(Math.random() * laneCount);
                    }
                });
            }
            else if (mode === 'redaction') {
                const scanY = (time * 100) % (h + 100) - 50;
                // Add dummy particles if empty
                if (state.particles.length === 0) {
                    for(let i=0; i<50; i++) {
                        state.particles.push({x: Math.random()*w, y: Math.random()*h, w: 20+Math.random()*40, h: 6});
                    }
                }

                state.particles.forEach((p: any) => {
                    const dist = Math.abs(p.y - scanY);
                    if (dist < 50) {
                        ctx.fillStyle = color;
                        ctx.globalAlpha = 1 - (dist/50);
                        ctx.fillRect(p.x, p.y, p.w, p.h);
                    } else {
                        ctx.fillStyle = 'rgba(255,255,255,0.05)';
                        ctx.globalAlpha = 1;
                        ctx.fillRect(p.x, p.y, p.w, p.h);
                    }
                });
                ctx.fillStyle = '#fff';
                ctx.fillRect(0, scanY, w, 2);
            }
            else if (mode === 'logic') {
                // Spawn Packets
                if (Math.random() > 0.98) {
                    const startNodes = state.nodes.filter((n: any) => n.type === 'trigger');
                    if (startNodes.length > 0) {
                        const start = startNodes[Math.floor(Math.random() * startNodes.length)];
                        state.nodes.forEach((n: any) => { if(n.id === start.id) n.active = 1.0; });

                        // Find links from this start
                        const links = state.links.filter((l: any) => l.from === start.id);
                        links.forEach((l: any) => {
                            state.packets.push({
                                fromId: l.from, toId: l.to, progress: 0, speed: 0.02 + Math.random() * 0.01
                            });
                        });
                    }
                }

                // Draw Links
                ctx.lineWidth = 2;
                state.links.forEach((l: any) => {
                    const n1 = state.nodes.find((n: any) => n.id === l.from);
                    const n2 = state.nodes.find((n: any) => n.id === l.to);

                    if (n1 && n2) {
                        const grad = ctx.createLinearGradient(n1.x, n1.y, n2.x, n2.y);
                        grad.addColorStop(0, 'rgba(255,255,255,0.1)');
                        grad.addColorStop(1, 'rgba(255,255,255,0.05)');
                        ctx.strokeStyle = grad;

                        ctx.beginPath();
                        ctx.moveTo(n1.x, n1.y);
                        const midX = (n1.x + n2.x) / 2;
                        ctx.bezierCurveTo(midX, n1.y, midX, n2.y, n2.x, n2.y);
                        ctx.stroke();
                    }
                });

                // Draw Packets
                for (let i = state.packets.length - 1; i >= 0; i--) {
                    const p = state.packets[i];
                    p.progress += p.speed;

                    const n1 = state.nodes.find((n: any) => n.id === p.fromId);
                    const n2 = state.nodes.find((n: any) => n.id === p.toId);

                    if (n1 && n2) {
                        const midX = (n1.x + n2.x) / 2;
                        const t = p.progress;
                        const invT = 1 - t;

                        const x = invT*invT*invT*n1.x + 3*invT*invT*t*midX + 3*invT*t*t*midX + t*t*t*n2.x;
                        const y = invT*invT*invT*n1.y + 3*invT*invT*t*n1.y + 3*invT*t*t*n2.y + t*t*t*n2.y;

                        ctx.fillStyle = color;
                        ctx.shadowBlur = 10; ctx.shadowColor = color;
                        ctx.beginPath(); ctx.arc(x, y, 3, 0, Math.PI*2); ctx.fill();
                        ctx.shadowBlur = 0;

                        if (p.progress >= 1) {
                            n2.active = 1.0;
                            const nextLinks = state.links.filter((l: any) => l.from === n2.id);
                            nextLinks.forEach((l: any) => {
                                state.packets.push({ fromId: l.from, toId: l.to, progress: 0, speed: 0.02 });
                            });
                            state.packets.splice(i, 1);
                        }
                    }
                }

                // Draw Nodes
                state.nodes.forEach((n: any) => {
                    const isActive = n.active > 0.01;
                    if (n.active > 0) n.active *= 0.95;

                    ctx.save();
                    ctx.translate(n.x, n.y);

                    if (n.type === 'trigger') {
                        ctx.fillStyle = isActive ? color : '#1a1a1c';
                        ctx.strokeStyle = isActive ? '#fff' : 'rgba(255,255,255,0.2)';
                        ctx.beginPath(); ctx.moveTo(0, -20); ctx.lineTo(20, 0); ctx.lineTo(0, 20); ctx.lineTo(-20, 0); ctx.closePath();
                    } else if (n.type === 'process') {
                        ctx.fillStyle = isActive ? color : '#1a1a1c';
                        ctx.strokeStyle = isActive ? '#fff' : 'rgba(255,255,255,0.2)';
                        drawRoundedRect(-40, -20, 80, 40, 4);
                    } else {
                        ctx.fillStyle = isActive ? color : '#1a1a1c';
                        ctx.strokeStyle = isActive ? '#fff' : 'rgba(255,255,255,0.2)';
                        drawRoundedRect(-30, -15, 60, 30, 15);
                    }

                    ctx.globalAlpha = isActive ? 0.8 : 0.5;
                    ctx.fill();
                    ctx.globalAlpha = 1;
                    ctx.lineWidth = 1;
                    ctx.stroke();

                    ctx.fillStyle = '#fff';
                    ctx.font = '9px monospace';
                    ctx.textAlign = 'center';
                    ctx.textBaseline = 'middle';

                    const textW = ctx.measureText(n.label).width;
                    ctx.fillStyle = 'rgba(0,0,0,0.6)';
                    ctx.fillRect(-textW/2 - 4, 22, textW + 8, 14);
                    ctx.fillStyle = isActive ? color : '#888';
                    ctx.fillText(n.label, 0, 29);

                    ctx.restore();
                });
            }
            else if (mode === 'core') {
                if (Math.random() > 0.96) {
                    state.nodes[0].active = 1; 
                    const startLinks = state.links.filter((l: any) => l.from === 0);
                    if (startLinks.length > 0) {
                        const startLink = startLinks[Math.floor(Math.random() * startLinks.length)];
                        state.particles.push({
                            linkIdx: state.links.indexOf(startLink),
                            t: 0,
                            speed: 0.08
                        });
                    }
                }

                ctx.translate(cx, cy);
                ctx.rotate(time * 0.05);

                ctx.strokeStyle = 'rgba(255,255,255,0.08)';
                ctx.lineWidth = 1;
                ctx.beginPath();
                state.links.forEach((l: any) => {
                    const n1 = state.nodes[l.from];
                    const n2 = state.nodes[l.to];
                    if (n1 && n2) {
                        ctx.moveTo(n1.x, n1.y);
                        ctx.lineTo(n2.x, n2.y);
                    }
                });
                ctx.stroke();

                state.nodes.forEach((n:any) => {
                    if (n.active > 0) {
                        ctx.fillStyle = color;
                        ctx.shadowBlur = 10 * n.active;
                        ctx.shadowColor = color;
                        n.active -= 0.05;
                    } else {
                        ctx.fillStyle = n.layer === 0 ? color : 'rgba(255,255,255,0.3)';
                        ctx.shadowBlur = 0;
                    }
                    const size = n.layer === 0 ? 4 : 2;
                    ctx.beginPath(); ctx.arc(n.x, n.y, size, 0, Math.PI*2); ctx.fill();
                    ctx.shadowBlur = 0;
                });

                for(let i=state.particles.length-1; i>=0; i--) {
                    const p = state.particles[i];
                    p.t += p.speed;
                    const link = state.links[p.linkIdx];
                    if (!link) { state.particles.splice(i,1); continue; }

                    const n1 = state.nodes[link.from];
                    const n2 = state.nodes[link.to];

                    if (n1 && n2) {
                        const currX = n1.x + (n2.x - n1.x) * p.t;
                        const currY = n1.y + (n2.y - n1.y) * p.t;
                        ctx.fillStyle = '#fff';
                        ctx.shadowBlur = 5; ctx.shadowColor = '#fff';
                        ctx.fillRect(currX-1.5, currY-1.5, 3, 3);
                        ctx.shadowBlur = 0;
                        if (p.t >= 1) {
                            n2.active = 1;
                            // Propagate
                            if (n2.layer < 3 && Math.random() > 0.3) {
                                const nextLinks = state.links
                                    .map((l: any, idx: number) => ({...l, idx}))
                                    .filter((l: any) => l.from === link.to);

                                if (nextLinks.length > 0) {
                                    const nextL = nextLinks[Math.floor(Math.random() * nextLinks.length)];
                                    state.particles.push({ linkIdx: nextL.idx, t: 0, speed: 0.08 });
                                }
                            }
                            state.particles.splice(i, 1);
                        }
                    } else {
                        state.particles.splice(i, 1);
                    }
                }
                ctx.rotate(-time * 0.05);
                ctx.translate(-cx, -cy);
            }
            // ... (Other modes: swarm, translation - omitted for brevity as they weren't reported broken, but pattern holds)
            else if (mode === 'swarm') {
                // (Keeping swarm logic intact as it was stable)
                // ... (Swarm logic from original file) ...
                // Re-inserted swarm logic for completeness to avoid regression
                const beltY = h * 0.65; 
                const inputEnd = w * 0.45;
                const outputStart = w * 0.55;
                const agentX = w * 0.5;
                const agentBaseY = beltY + 40;

                const boxSize = 18;
                const speed = 1.0; 
                const animSpeed = 0.03;

                const COLORS = ['#22d3ee', '#a78bfa', '#fbbf24']; 
                const TARGET_YS = [beltY - 80, beltY - 40, beltY];

                const lastBox = state.boxes.length > 0 ? state.boxes[state.boxes.length - 1] : null;
                const safeToSpawn = !lastBox || (lastBox.x > 80); 

                if (safeToSpawn && Math.random() > 0.99) {
                    const typeIdx = Math.floor(Math.random() * 3);
                    state.boxes.push({
                        x: -20,
                        y: beltY - boxSize,
                        w: boxSize,
                        h: boxSize,
                        color: COLORS[typeIdx],
                        targetLane: typeIdx,
                        state: 'conveyor_in' 
                    });
                }

                ctx.fillStyle = 'rgba(255,255,255,0.1)';
                ctx.fillRect(0, beltY, inputEnd, 4);
                TARGET_YS.forEach(y => {
                    ctx.fillRect(outputStart, y + boxSize, w - outputStart, 4);
                });

                ctx.fillStyle = 'rgba(255,255,255,0.2)';
                const dashOffset = (time * 60) % 40; 
                for(let i=0; i<inputEnd; i+=40) {
                    const x = i + dashOffset;
                    if(x < inputEnd) ctx.fillRect(x, beltY, 4, 4);
                }
                TARGET_YS.forEach(y => {
                    for(let i=outputStart; i<w; i+=40) {
                        const x = i + dashOffset; 
                        if(x > outputStart) ctx.fillRect(x, y + boxSize, 4, 4);
                    }
                });

                const agent = state.agent;
                ctx.fillStyle = '#333';
                ctx.fillRect(agentX - 15, agentBaseY - 20, 30, 20); 

                const pivotX = agentX;
                const pivotY = agentBaseY - 20;

                let armX = pivotX;
                let armY = beltY - 60; 
                let grabberGap = 10;

                if (agent.state === 'idle') {
                    const target = state.boxes.find((b: any) => 
                        b.state === 'conveyor_in' && 
                        b.x > inputEnd - 60 && 
                        b.x < inputEnd
                    );
                    if (target) {
                        agent.state = 'reaching';
                        agent.targetBox = target;
                        agent.t = 0;
                    }
                }

                if (agent.state === 'reaching') {
                    agent.t += animSpeed;
                    const t = Math.min(1, agent.t);
                    const b = agent.targetBox;
                    if (b) {
                        if(b.x < inputEnd - 20) b.x += speed;
                        armX = pivotX + (b.x + b.w/2 - pivotX) * t;
                        armY = (pivotY - 80) + (b.y - (pivotY - 80)) * t;
                        if (t >= 1) { agent.state = 'grasping'; agent.t = 0; }
                    } else {
                        agent.state = 'idle'; // Reset if target gone
                    }
                } 
                else if (agent.state === 'grasping') {
                    agent.t += animSpeed * 2;
                    grabberGap = 10 * (1 - Math.min(1, agent.t));
                    if (agent.targetBox) {
                        armX = agent.targetBox.x + agent.targetBox.w/2;
                        armY = agent.targetBox.y;
                    }
                    if (agent.t >= 1) { agent.state = 'moving'; if(agent.targetBox) agent.targetBox.state = 'lifted'; agent.t = 0; }
                }
                else if (agent.state === 'moving') {
                    agent.t += animSpeed;
                    const t = Math.min(1, agent.t);
                    const b = agent.targetBox;
                    if (b) {
                        const targetY = TARGET_YS[b.targetLane];

                        const startX = inputEnd - 20;
                        const targetX = outputStart + 20;

                        armX = startX + (targetX - startX) * t;
                        const midY = Math.min(beltY, targetY) - 60;
                        armY = (1-t)*(1-t)*beltY + 2*(1-t)*t*midY + t*t*targetY;

                        grabberGap = 0;
                        b.x = armX - b.w/2;
                        b.y = armY;

                        if (t >= 1) { agent.state = 'releasing'; agent.t = 0; }
                    }
                }
                else if (agent.state === 'releasing') {
                    agent.t += animSpeed * 2;
                    const b = agent.targetBox;
                    if (b) {
                        armX = b.x + b.w/2;
                        armY = b.y;
                        grabberGap = 10 * Math.min(1, agent.t);

                        if (agent.t >= 1) {
                            b.state = 'conveyor_out';
                            b.y = TARGET_YS[b.targetLane];
                            agent.state = 'returning';
                            agent.targetBox = null;
                            agent.t = 0;
                        }
                    }
                }
                else if (agent.state === 'returning') {
                    agent.t += animSpeed;
                    const t = Math.min(1, agent.t);
                    const startX = outputStart + 20;
                    const startY = armY;
                    const targetX = pivotX;
                    const targetY = beltY - 60;
                    armX = startX + (targetX - startX) * t;
                    armY = startY + (targetY - startY) * t;
                    if (t >= 1) agent.state = 'idle';
                }
                else {
                    armX = pivotX + Math.sin(time * 2) * 5;
                    armY = beltY - 60 + Math.cos(time * 3) * 5;
                }

                ctx.strokeStyle = color;
                ctx.lineWidth = 2;
                ctx.beginPath();
                ctx.moveTo(pivotX, pivotY);
                const elbowX = (pivotX + armX) / 2 - 20; 
                const elbowY = Math.min(pivotY, armY) - 30;
                ctx.quadraticCurveTo(elbowX, elbowY, armX, armY);
                ctx.stroke();

                ctx.fillStyle = '#fff';
                ctx.beginPath(); ctx.arc(pivotX, pivotY, 3, 0, Math.PI*2); ctx.fill();
                ctx.beginPath(); ctx.arc(armX, armY, 3, 0, Math.PI*2); ctx.fill();

                ctx.save();
                ctx.translate(armX, armY);
                ctx.fillStyle = color;
                ctx.fillRect(-8 - grabberGap/2, -5, 4, 15);
                ctx.fillRect(4 + grabberGap/2, -5, 4, 15);
                ctx.restore();

                for (let i = state.boxes.length - 1; i >= 0; i--) {
                    const b = state.boxes[i];
                    if (b.state === 'conveyor_in') {
                        if (agent.targetBox !== b || agent.state === 'reaching') {
                             if (b.x < inputEnd - 20) b.x += speed; 
                        }
                    } else if (b.state === 'conveyor_out') {
                        b.x += speed;
                    }
                    if (b.x > w + 20) { state.boxes.splice(i, 1); continue; }

                    ctx.fillStyle = b.color;
                    ctx.strokeStyle = '#fff';
                    ctx.lineWidth = 1;
                    ctx.fillRect(b.x, b.y, b.w, b.h);
                    ctx.strokeRect(b.x, b.y, b.w, b.h);
                    ctx.fillStyle = 'rgba(0,0,0,0.3)';
                    ctx.fillRect(b.x + 2, b.y + 2, 4, 4);
                }
            } else if (mode === 'translation') {
                // Translation mode logic
                const colWidth = 140; 
                const numCols = 2; 
                const SNIPPETS = ["POST /api/v1/ingest", "{ id: '8f3a' }", "WARN: Latency", "Converting...", "0x4F3E21", "SELECT * FROM logs", "Processing...", "struct Node", "ERROR: Timeout", "> System.init()"];

                if (state.columns.length === 0) {
                    state.columns = Array.from({ length: numCols }, (_, i) => ({
                        x: 20 + i * (colWidth + 10),
                        y: Math.random() * h,
                        speed: 0.5 + Math.random() * 0.5,
                        items: Array.from({ length: 15 }, () => ({
                            text: SNIPPETS[Math.floor(Math.random() * SNIPPETS.length)],
                            y: 0 
                        }))
                    }));
                }

                const gridStartX = w * 0.55;
                const gridCols = 6; const gridRows = 8;
                const cellW = (w * 0.4) / gridCols; const cellH = h / gridRows;
                if (state.grid.length === 0) {
                    for(let i=0; i<gridCols*gridRows; i++) {
                        state.grid.push({
                            x: gridStartX + (i % gridCols) * cellW + cellW/2,
                            y: Math.floor(i / gridCols) * cellH + cellH/2,
                            filled: false, alpha: 0.2
                        });
                    }
                }

                ctx.font = '10px monospace';
                ctx.textAlign = 'left';

                state.columns.forEach((col: any) => {
                    col.y -= col.speed;
                    if (col.y < -300) col.y = h; 

                    col.items.forEach((item: any, i: number) => {
                        const yPos = col.y + i * 20;
                        const drawnY = yPos % (h + 300) - 50;

                        if (drawnY > -20 && drawnY < h + 20) {
                            const isScanned = Math.abs(drawnY - h/2) < 20;
                            ctx.fillStyle = isScanned ? '#fff' : 'rgba(255,255,255,0.3)';
                            if (isScanned) {
                                if (Math.random() > 0.98) {
                                    const empty = state.grid.filter((g: any) => !g.filled);
                                    if (empty.length > 0) {
                                        const t = empty[Math.floor(Math.random() * empty.length)];
                                        t.filled = true;
                                        state.particles.push({
                                            x: col.x + 80, y: drawnY,
                                            tx: t.x, ty: t.y,
                                            progress: 0, speed: 0.05,
                                            target: t
                                        });
                                    }
                                }
                            }
                            ctx.fillText(item.text, col.x, drawnY);
                        }
                    });
                });

                ctx.fillStyle = color;
                ctx.globalAlpha = 0.1;
                ctx.fillRect(0, h/2 - 20, w * 0.45, 40);
                ctx.globalAlpha = 0.8;
                ctx.fillRect(0, h/2, w * 0.45, 1);

                ctx.globalAlpha = 1;
                for (let i = state.particles.length - 1; i >= 0; i--) {
                    const p = state.particles[i];
                    p.progress += p.speed;
                    const t = p.progress;
                    const lx = p.x + (p.tx - p.x) * t;
                    const ly = p.y + (p.ty - p.y) * t;

                    ctx.fillStyle = color;
                    ctx.fillRect(lx - 2, ly - 2, 4, 4);

                    if (p.progress >= 1) {
                        p.target.alpha = 1.0;
                        state.particles.splice(i, 1);
                    }
                }

                state.grid.forEach((cell: any) => {
                    if (cell.filled) cell.alpha = Math.max(0.4, cell.alpha - 0.02);
                    else cell.alpha = 0.1;
                    const s = Math.min(cellW, cellH) * 0.6;
                    ctx.strokeStyle = color; ctx.globalAlpha = cell.alpha; ctx.lineWidth = 1;
                    ctx.strokeRect(cell.x - s/2, cell.y - s/2, s, s);
                    if (cell.filled) {
                        ctx.fillStyle = color; ctx.globalAlpha = cell.alpha * 0.6;
                        ctx.fillRect(cell.x - s/2 + 2, cell.y - s/2 + 2, s - 4, s - 4);
                        if (Math.random() > 0.995) cell.filled = false;
                    }
                });
            }

            ctx.globalAlpha = 1;
            frameId = requestAnimationFrame(render);
        };

        const observer = new ResizeObserver(() => { 
            // Debounce resize to prevent loop error
            window.requestAnimationFrame(() => resize()); 
        });
        observer.observe(container);

        // Initial setup
        resize();
        render();

        return () => {
            observer.disconnect();
            cancelAnimationFrame(frameId);
        };
    }, [mode, color]);

    return (
        <div ref={containerRef} className="w-full h-full relative overflow-hidden bg-[#0c0c0e]">
            <canvas ref={canvasRef} className="block absolute top-0 left-0" />
            <div className="absolute inset-0 pointer-events-none opacity-20" style={{ backgroundImage: 'linear-gradient(rgba(18, 16, 16, 0) 50%, rgba(0, 0, 0, 0.25) 50%), linear-gradient(90deg, rgba(255, 0, 0, 0.06), rgba(0, 255, 0, 0.02), rgba(0, 0, 255, 0.06))', backgroundSize: '100% 2px, 3px 100%' }} />
        </div>
    );
};

import React, { useEffect, useRef } from 'react';

interface SectionVisualizerProps {
    mode: 'search' | 'redaction' | 'logic' | 'core' | 'shield' | 'swarm' | 'predictive' | 'translation' | 'identity';
    color: string;
}

export const SectionVisualizer: React.FC<SectionVisualizerProps> = ({ mode, color }) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const containerRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        const canvas = canvasRef.current;
        const container = containerRef.current;
        if (!canvas || !container) return;

        const ctx = canvas.getContext('2d', { alpha: true });
        if (!ctx) return;

        let frameId: number;
        let time = 0;

        // --- HELPER: Polyfill for roundRect ---
        const drawRoundedRect = (x: number, y: number, w: number, h: number, r: number) => {
            if (ctx.roundRect) {
                ctx.beginPath();
                ctx.roundRect(x, y, w, h, r);
                return;
            }
            // Fallback for browsers without roundRect
            ctx.beginPath();
            ctx.moveTo(x + r, y);
            ctx.lineTo(x + w - r, y);
            ctx.quadraticCurveTo(x + w, y, x + w, y + r);
            ctx.lineTo(x + w, y + h - r);
            ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
            ctx.lineTo(x + r, y + h);
            ctx.quadraticCurveTo(x, y + h, x, y + h - r);
            ctx.lineTo(x, y + r);
            ctx.quadraticCurveTo(x, y, x + r, y);
            ctx.closePath();
        };

        // --- STATE MANAGEMENT ---
        const state: any = {
            width: 0,
            height: 0,
            particles: [],
            nodes: [],
            links: [], 
            grid: [],
            columns: [], 
            task: null, 
            agent: { state: 'idle', t: 0, heldBox: null, armHeight: 0, armExt: 0 },
            boxes: [], 
            stack: [],
            // Identity Mode (Augmentation HUD) State
            radarAngle: 0,
            activeInsightIndex: 0,
            insightTimer: 0,
            knowledgeNodes: [],
            dataPackets: [],
            insights: [
                { title: "Compliance Alert", type: "warning", text: "Clause 4.2 conflicts with new EU regulations.", meta: "Source: Legal_KB_v9" },
                { title: "Expertise Found", type: "success", text: "Similar project completed by S. Chen in 2024.", meta: "Connect: @schen" },
                { title: "Asset Retrieval", type: "info", text: "Loading architectural blueprints...", meta: "File: Project_Titan.dwg" },
                { title: "Risk Analysis", type: "warning", text: "Budget variance predicted > 15%.", meta: "Model: Fin_Ops_Q3" }
            ],
            // Logic/Strategy Mode State
            packets: [],
            initializedMode: null
        };

        const init = (w: number, h: number) => {
            state.particles = [];
            state.nodes = [];
            state.links = [];
            state.grid = [];
            state.columns = [];
            state.task = null;
            state.boxes = [];
            state.stack = [];
            state.packets = [];
            state.agent = { state: 'idle', t: 0, heldBox: null, armHeight: 0, armExt: 0 };

            state.initializedMode = mode;

            if (mode === 'identity') {
                // Initialize "Knowledge Constellation" around the center user
                const cx = w * 0.3; // User is to the left
                const cy = h * 0.5;
                state.knowledgeNodes = [];
                const labels = ["LEGAL", "HISTORY", "FINANCE", "TECH", "HR"];

                for(let i=0; i<5; i++) {
                    const angle = (i / 5) * Math.PI * 2 - Math.PI/2;
                    const r = 120;
                    state.knowledgeNodes.push({
                        x: cx + Math.cos(angle) * r,
                        y: cy + Math.sin(angle) * r,
                        label: labels[i],
                        active: 0
                    });
                }
                state.dataPackets = [];
                state.activeInsightIndex = 0;
                state.insightTimer = 0;
            }
            else if (mode === 'search') {
                const particleCount = 80;
                for(let i=0; i<particleCount; i++) {
                    state.particles.push({
                        x: Math.random() * w,
                        y: Math.random() * h,
                        vx: 2 + Math.random() * 1.5,
                        vy: (Math.random() - 0.5) * 0.5,
                        targetLane: Math.floor(Math.random() * 5),
                        size: 0.5 + Math.random() * 0.5
                    });
                }
            }
            else if (mode === 'logic') {
                // STRATEGY BUILDER
                state.nodes.push({ id: 0, x: w * 0.15, y: h * 0.3, label: "DEMAND SPIKE", type: 'trigger', active: 0 });
                state.nodes.push({ id: 1, x: w * 0.15, y: h * 0.7, label: "INVENTORY LOW", type: 'trigger', active: 0 });
                state.nodes.push({ id: 2, x: w * 0.45, y: h * 0.5, label: "ALLOCATION LOGIC", type: 'process', active: 0 });
                state.nodes.push({ id: 3, x: w * 0.75, y: h * 0.25, label: "PRIORITY: RETAIL", type: 'action', active: 0 });
                state.nodes.push({ id: 4, x: w * 0.75, y: h * 0.75, label: "LIMIT WHOLESALE", type: 'action', active: 0 });
                state.links.push({ from: 0, to: 2 });
                state.links.push({ from: 1, to: 2 });
                state.links.push({ from: 2, to: 3 });
                state.links.push({ from: 2, to: 4 });
            }
            else if (mode === 'core') {
                // KNOWLEDGE TREE - Initialize here to avoid render-loop race conditions
                // Root
                state.nodes.push({id:0, x: 0, y: 0, layer: 0});

                // Layers
                const layerCounts = [6, 12, 18];
                let idCounter = 1;

                // Create nodes first
                // Layer 1
                for(let i=0; i<layerCounts[0]; i++) {
                    const angle = (i / layerCounts[0]) * Math.PI * 2;
                    state.nodes.push({
                        id: idCounter++,
                        x: Math.cos(angle) * 60,
                        y: Math.sin(angle) * 60,
                        layer: 1
                    });
                }
                // Layer 2
                for(let i=0; i<layerCounts[1]; i++) {
                    const angle = (i / layerCounts[1]) * Math.PI * 2 + 0.2;
                    state.nodes.push({
                        id: idCounter++,
                        x: Math.cos(angle) * 120,
                        y: Math.sin(angle) * 120,
                        layer: 2
                    });
                }

                // Links
                // Root to Layer 1
                for(let i=1; i<=layerCounts[0]; i++) {
                    state.links.push({from: 0, to: i});
                }
                // Layer 1 to Layer 2 (Simple fan out)
                for(let i=0; i<layerCounts[1]; i++) {
                    const targetNodeId = 1 + layerCounts[0] + i; // Start after layer 1
                    const sourceNodeId = 1 + Math.floor(i / 2); // Connect 2 outer to 1 inner
                    if(state.nodes[targetNodeId] && state.nodes[sourceNodeId]) {
                        state.links.push({from: sourceNodeId, to: targetNodeId});
                    }
                }
            }
        };

        const resize = () => {
            const rect = container.getBoundingClientRect();
            if (rect.width === 0 || rect.height === 0) return;

            const dpr = window.devicePixelRatio || 1;

            canvas.width = rect.width * dpr;
            canvas.height = rect.height * dpr;

            canvas.style.width = `${rect.width}px`;
            canvas.style.height = `${rect.height}px`;

            ctx.scale(dpr, dpr);

            state.width = rect.width;
            state.height = rect.height;

            // Re-init if dimensions change significantly or mode changed
            if (mode !== state.initializedMode || Math.abs(state.width - rect.width) > 10) {
                init(rect.width, rect.height);
            }
        };

        const render = () => {
            time += 0.01;
            const w = state.width;
            const h = state.height;
            const cx = w/2;
            const cy = h/2;

            ctx.clearRect(0, 0, w, h);

            if (mode === 'identity') {
                // --- WORKFORCE AUGMENTATION HUD ---

                const userX = w * 0.35;
                const userY = h * 0.5;

                state.insightTimer += 1;

                // 1. CYCLE LOGIC
                if (state.insightTimer > 300) { // Every 5 seconds
                    state.activeInsightIndex = (state.activeInsightIndex + 1) % state.insights.length;
                    state.insightTimer = 0;

                    // Trigger packet burst
                    for(let i=0; i<5; i++) {
                        // Pick random knowledge node
                        const nodeIdx = Math.floor(Math.random() * state.knowledgeNodes.length);
                        const node = state.knowledgeNodes[nodeIdx];
                        state.knowledgeNodes[nodeIdx].active = 1.0;

                        state.dataPackets.push({
                            x: node.x, y: node.y,
                            tx: userX, ty: userY,
                            progress: 0,
                            speed: 0.02 + Math.random() * 0.02
                        });
                    }
                }

                // 2. DRAW KNOWLEDGE CONSTELLATION
                state.knowledgeNodes.forEach((node: any) => {
                    // Decay activity
                    node.active *= 0.96;

                    // Draw Connection
                    ctx.beginPath();
                    ctx.moveTo(node.x, node.y);
                    ctx.lineTo(userX, userY);
                    ctx.lineWidth = 1;
                    const grad = ctx.createLinearGradient(node.x, node.y, userX, userY);
                    grad.addColorStop(0, `rgba(255,255,255,${0.1 + node.active * 0.5})`);
                    grad.addColorStop(1, 'transparent');
                    ctx.strokeStyle = grad;
                    ctx.stroke();

                    // Draw Node
                    ctx.fillStyle = '#0c0c0e';
                    ctx.beginPath(); ctx.arc(node.x, node.y, 4, 0, Math.PI*2); ctx.fill();
                    ctx.strokeStyle = color;
                    ctx.lineWidth = 1;
                    ctx.stroke();

                    // Label
                    ctx.fillStyle = `rgba(255,255,255,${0.3 + node.active})`;
                    ctx.font = '9px monospace';
                    ctx.textAlign = 'center';
                    ctx.fillText(node.label, node.x, node.y - 10);
                });

                // 3. DRAW DATA PACKETS
                for (let i = state.dataPackets.length - 1; i >= 0; i--) {
                    const p = state.dataPackets[i];
                    p.progress += p.speed;

                    const curX = p.x + (p.tx - p.x) * p.progress;
                    const curY = p.y + (p.ty - p.y) * p.progress;

                    ctx.fillStyle = '#fff';
                    ctx.shadowBlur = 5; ctx.shadowColor = color;
                    ctx.fillRect(curX - 1.5, curY - 1.5, 3, 3);
                    ctx.shadowBlur = 0;

                    if (p.progress >= 1) state.dataPackets.splice(i, 1);
                }

                // 4. CENTRAL USER (Fingerprint / Reticle)
                state.radarAngle += 0.02;

                ctx.save();
                ctx.translate(userX, userY);

                // Rotating Ring
                ctx.strokeStyle = `rgba(255,255,255,0.1)`;
                ctx.beginPath(); ctx.arc(0, 0, 30, 0, Math.PI*2); ctx.stroke();

                ctx.rotate(state.radarAngle);
                ctx.beginPath(); ctx.arc(0, 0, 34, 0, Math.PI * 1.5); ctx.strokeStyle = color; ctx.stroke();
                ctx.restore();

                // User Icon
                ctx.fillStyle = '#fff';
                ctx.beginPath(); ctx.arc(userX, userY, 2, 0, Math.PI*2); ctx.fill();
                ctx.fillStyle = 'rgba(255,255,255,0.5)';
                ctx.font = '10px monospace';
                ctx.fillText("USER_CONTEXT", userX, userY + 50);

                // 5. INSIGHT CARDS (Right Side)
                const activeInsight = state.insights[state.activeInsightIndex];
                const cardX = w * 0.6;
                const cardY = h * 0.35;

                // Animation In/Out based on timer
                // 0-20: Fade In, 20-280: Hold, 280-300: Fade Out
                let opacity = 0;
                let yOffset = 10;

                if (state.insightTimer < 30) {
                    const t = state.insightTimer / 30;
                    opacity = t;
                    yOffset = 10 * (1-t);
                } else if (state.insightTimer > 270) {
                    const t = (300 - state.insightTimer) / 30;
                    opacity = t;
                    yOffset = -10 * (1-t);
                } else {
                    opacity = 1;
                    yOffset = 0;
                }

                if (opacity > 0) {
                    ctx.save();
                    ctx.translate(0, yOffset);
                    ctx.globalAlpha = opacity;

                    // Connecting Line from User to Card
                    ctx.beginPath();
                    ctx.moveTo(userX + 40, userY);
                    ctx.lineTo(cardX - 20, cardY + 40);
                    ctx.strokeStyle = `rgba(255,255,255,${0.2 * opacity})`;
                    ctx.setLineDash([2, 4]);
                    ctx.stroke();
                    ctx.setLineDash([]);

                    // Card Body
                    ctx.fillStyle = 'rgba(20, 20, 25, 0.8)';
                    ctx.strokeStyle = 'rgba(255,255,255,0.15)';
                    drawRoundedRect(cardX, cardY, 240, 90, 8);
                    ctx.fill();
                    ctx.stroke();

                    // Accent Bar
                    ctx.fillStyle = activeInsight.type === 'warning' ? '#ef4444' : activeInsight.type === 'success' ? '#22c55e' : color;
                    ctx.fillRect(cardX, cardY + 10, 3, 70);

                    // Text
                    ctx.textAlign = 'left';
                    ctx.fillStyle = '#fff';
                    ctx.font = 'bold 12px sans-serif';
                    ctx.fillText(activeInsight.title, cardX + 20, cardY + 25);

                    ctx.fillStyle = 'rgba(255,255,255,0.7)';
                    ctx.font = '11px sans-serif';
                    // Simple wrap logic
                    const words = activeInsight.text.split(' ');
                    let line = "";
                    let ly = cardY + 45;
                    for(let i=0; i<words.length; i++) {
                        const testLine = line + words[i] + " ";
                        if (ctx.measureText(testLine).width > 200) {
                            ctx.fillText(line, cardX + 20, ly);
                            line = words[i] + " ";
                            ly += 15;
                        } else {
                            line = testLine;
                        }
                    }
                    ctx.fillText(line, cardX + 20, ly);

                    // Meta
                    ctx.fillStyle = 'rgba(255,255,255,0.4)';
                    ctx.font = '9px monospace';
                    ctx.fillText(activeInsight.meta, cardX + 20, cardY + 80);

                    ctx.restore();
                }
            }
            else if (mode === 'search') {
                const processLine = w * 0.4;
                const laneCount = 5;
                const laneHeight = h / laneCount;

                ctx.lineWidth = 1;
                ctx.strokeStyle = 'rgba(255, 255, 255, 0.08)';
                for(let i=0; i<laneCount; i++) {
                    const ly = i * laneHeight + laneHeight/2;
                    ctx.beginPath(); ctx.moveTo(processLine, ly); ctx.lineTo(w, ly); ctx.stroke();
                }

                const scannerGlow = ctx.createLinearGradient(processLine, 0, processLine + 60, 0);
                scannerGlow.addColorStop(0, color);
                scannerGlow.addColorStop(1, 'transparent');
                ctx.fillStyle = scannerGlow;
                ctx.globalAlpha = 0.15;
                ctx.fillRect(processLine, 0, 60, h);

                ctx.fillStyle = color;
                ctx.globalAlpha = 0.8;
                ctx.fillRect(processLine, 0, 2, h);

                state.particles.forEach((p: any) => {
                    p.x += p.vx;
                    if (p.x < processLine) {
                        p.y += p.vy;
                        if (p.y < 0) p.y += h;
                        if (p.y > h) p.y -= h;
                        ctx.fillStyle = 'rgba(255, 255, 255, 0.4)';
                        ctx.globalAlpha = 0.6;
                        ctx.beginPath(); ctx.arc(p.x, p.y, p.size * 2, 0, Math.PI*2); ctx.fill();
                    } else {
                        const targetY = p.targetLane * laneHeight + laneHeight/2;
                        p.y += (targetY - p.y) * 0.15; 
                        p.x += 1.5; 
                        ctx.fillStyle = color;
                        ctx.globalAlpha = 1;
                        const packetWidth = 20 * p.size;
                        const packetHeight = 4;
                        ctx.shadowColor = color; ctx.shadowBlur = 10;
                        ctx.fillRect(p.x, p.y - packetHeight/2, packetWidth, packetHeight);
                        ctx.shadowBlur = 0;
                    }
                    if (p.x > w + 50) {
                        p.x = -20;
                        p.y = Math.random() * h;
                        p.vx = 2 + Math.random() * 1.5;
                        p.targetLane = Math.floor(Math.random() * laneCount);
                    }
                });
            }
            else if (mode === 'redaction') {
                const scanY = (time * 100) % (h + 100) - 50;
                // Add dummy particles if empty
                if (state.particles.length === 0) {
                    for(let i=0; i<50; i++) {
                        state.particles.push({x: Math.random()*w, y: Math.random()*h, w: 20+Math.random()*40, h: 6});
                    }
                }

                state.particles.forEach((p: any) => {
                    const dist = Math.abs(p.y - scanY);
                    if (dist < 50) {
                        ctx.fillStyle = color;
                        ctx.globalAlpha = 1 - (dist/50);
                        ctx.fillRect(p.x, p.y, p.w, p.h);
                    } else {
                        ctx.fillStyle = 'rgba(255,255,255,0.05)';
                        ctx.globalAlpha = 1;
                        ctx.fillRect(p.x, p.y, p.w, p.h);
                    }
                });
                ctx.fillStyle = '#fff';
                ctx.fillRect(0, scanY, w, 2);
            }
            else if (mode === 'logic') {
                // Spawn Packets
                if (Math.random() > 0.98) {
                    const startNodes = state.nodes.filter((n: any) => n.type === 'trigger');
                    if (startNodes.length > 0) {
                        const start = startNodes[Math.floor(Math.random() * startNodes.length)];
                        state.nodes.forEach((n: any) => { if(n.id === start.id) n.active = 1.0; });

                        // Find links from this start
                        const links = state.links.filter((l: any) => l.from === start.id);
                        links.forEach((l: any) => {
                            state.packets.push({
                                fromId: l.from, toId: l.to, progress: 0, speed: 0.02 + Math.random() * 0.01
                            });
                        });
                    }
                }

                // Draw Links
                ctx.lineWidth = 2;
                state.links.forEach((l: any) => {
                    const n1 = state.nodes.find((n: any) => n.id === l.from);
                    const n2 = state.nodes.find((n: any) => n.id === l.to);

                    if (n1 && n2) {
                        const grad = ctx.createLinearGradient(n1.x, n1.y, n2.x, n2.y);
                        grad.addColorStop(0, 'rgba(255,255,255,0.1)');
                        grad.addColorStop(1, 'rgba(255,255,255,0.05)');
                        ctx.strokeStyle = grad;

                        ctx.beginPath();
                        ctx.moveTo(n1.x, n1.y);
                        const midX = (n1.x + n2.x) / 2;
                        ctx.bezierCurveTo(midX, n1.y, midX, n2.y, n2.x, n2.y);
                        ctx.stroke();
                    }
                });

                // Draw Packets
                for (let i = state.packets.length - 1; i >= 0; i--) {
                    const p = state.packets[i];
                    p.progress += p.speed;

                    const n1 = state.nodes.find((n: any) => n.id === p.fromId);
                    const n2 = state.nodes.find((n: any) => n.id === p.toId);

                    if (n1 && n2) {
                        const midX = (n1.x + n2.x) / 2;
                        const t = p.progress;
                        const invT = 1 - t;

                        const x = invT*invT*invT*n1.x + 3*invT*invT*t*midX + 3*invT*t*t*midX + t*t*t*n2.x;
                        const y = invT*invT*invT*n1.y + 3*invT*invT*t*n1.y + 3*invT*t*t*n2.y + t*t*t*n2.y;

                        ctx.fillStyle = color;
                        ctx.shadowBlur = 10; ctx.shadowColor = color;
                        ctx.beginPath(); ctx.arc(x, y, 3, 0, Math.PI*2); ctx.fill();
                        ctx.shadowBlur = 0;

                        if (p.progress >= 1) {
                            n2.active = 1.0;
                            const nextLinks = state.links.filter((l: any) => l.from === n2.id);
                            nextLinks.forEach((l: any) => {
                                state.packets.push({ fromId: l.from, toId: l.to, progress: 0, speed: 0.02 });
                            });
                            state.packets.splice(i, 1);
                        }
                    }
                }

                // Draw Nodes
                state.nodes.forEach((n: any) => {
                    const isActive = n.active > 0.01;
                    if (n.active > 0) n.active *= 0.95;

                    ctx.save();
                    ctx.translate(n.x, n.y);

                    if (n.type === 'trigger') {
                        ctx.fillStyle = isActive ? color : '#1a1a1c';
                        ctx.strokeStyle = isActive ? '#fff' : 'rgba(255,255,255,0.2)';
                        ctx.beginPath(); ctx.moveTo(0, -20); ctx.lineTo(20, 0); ctx.lineTo(0, 20); ctx.lineTo(-20, 0); ctx.closePath();
                    } else if (n.type === 'process') {
                        ctx.fillStyle = isActive ? color : '#1a1a1c';
                        ctx.strokeStyle = isActive ? '#fff' : 'rgba(255,255,255,0.2)';
                        drawRoundedRect(-40, -20, 80, 40, 4);
                    } else {
                        ctx.fillStyle = isActive ? color : '#1a1a1c';
                        ctx.strokeStyle = isActive ? '#fff' : 'rgba(255,255,255,0.2)';
                        drawRoundedRect(-30, -15, 60, 30, 15);
                    }

                    ctx.globalAlpha = isActive ? 0.8 : 0.5;
                    ctx.fill();
                    ctx.globalAlpha = 1;
                    ctx.lineWidth = 1;
                    ctx.stroke();

                    ctx.fillStyle = '#fff';
                    ctx.font = '9px monospace';
                    ctx.textAlign = 'center';
                    ctx.textBaseline = 'middle';

                    const textW = ctx.measureText(n.label).width;
                    ctx.fillStyle = 'rgba(0,0,0,0.6)';
                    ctx.fillRect(-textW/2 - 4, 22, textW + 8, 14);
                    ctx.fillStyle = isActive ? color : '#888';
                    ctx.fillText(n.label, 0, 29);

                    ctx.restore();
                });
            }
            else if (mode === 'core') {
                if (Math.random() > 0.96) {
                    state.nodes[0].active = 1; 
                    const startLinks = state.links.filter((l: any) => l.from === 0);
                    if (startLinks.length > 0) {
                        const startLink = startLinks[Math.floor(Math.random() * startLinks.length)];
                        state.particles.push({
                            linkIdx: state.links.indexOf(startLink),
                            t: 0,
                            speed: 0.08
                        });
                    }
                }

                ctx.translate(cx, cy);
                ctx.rotate(time * 0.05);

                ctx.strokeStyle = 'rgba(255,255,255,0.08)';
                ctx.lineWidth = 1;
                ctx.beginPath();
                state.links.forEach((l: any) => {
                    const n1 = state.nodes[l.from];
                    const n2 = state.nodes[l.to];
                    if (n1 && n2) {
                        ctx.moveTo(n1.x, n1.y);
                        ctx.lineTo(n2.x, n2.y);
                    }
                });
                ctx.stroke();

                state.nodes.forEach((n:any) => {
                    if (n.active > 0) {
                        ctx.fillStyle = color;
                        ctx.shadowBlur = 10 * n.active;
                        ctx.shadowColor = color;
                        n.active -= 0.05;
                    } else {
                        ctx.fillStyle = n.layer === 0 ? color : 'rgba(255,255,255,0.3)';
                        ctx.shadowBlur = 0;
                    }
                    const size = n.layer === 0 ? 4 : 2;
                    ctx.beginPath(); ctx.arc(n.x, n.y, size, 0, Math.PI*2); ctx.fill();
                    ctx.shadowBlur = 0;
                });

                for(let i=state.particles.length-1; i>=0; i--) {
                    const p = state.particles[i];
                    p.t += p.speed;
                    const link = state.links[p.linkIdx];
                    if (!link) { state.particles.splice(i,1); continue; }

                    const n1 = state.nodes[link.from];
                    const n2 = state.nodes[link.to];

                    if (n1 && n2) {
                        const currX = n1.x + (n2.x - n1.x) * p.t;
                        const currY = n1.y + (n2.y - n1.y) * p.t;
                        ctx.fillStyle = '#fff';
                        ctx.shadowBlur = 5; ctx.shadowColor = '#fff';
                        ctx.fillRect(currX-1.5, currY-1.5, 3, 3);
                        ctx.shadowBlur = 0;
                        if (p.t >= 1) {
                            n2.active = 1;
                            // Propagate
                            if (n2.layer < 3 && Math.random() > 0.3) {
                                const nextLinks = state.links
                                    .map((l: any, idx: number) => ({...l, idx}))
                                    .filter((l: any) => l.from === link.to);

                                if (nextLinks.length > 0) {
                                    const nextL = nextLinks[Math.floor(Math.random() * nextLinks.length)];
                                    state.particles.push({ linkIdx: nextL.idx, t: 0, speed: 0.08 });
                                }
                            }
                            state.particles.splice(i, 1);
                        }
                    } else {
                        state.particles.splice(i, 1);
                    }
                }
                ctx.rotate(-time * 0.05);
                ctx.translate(-cx, -cy);
            }
            // ... (Other modes: swarm, translation - omitted for brevity as they weren't reported broken, but pattern holds)
            else if (mode === 'swarm') {
                // (Keeping swarm logic intact as it was stable)
                // ... (Swarm logic from original file) ...
                // Re-inserted swarm logic for completeness to avoid regression
                const beltY = h * 0.65; 
                const inputEnd = w * 0.45;
                const outputStart = w * 0.55;
                const agentX = w * 0.5;
                const agentBaseY = beltY + 40;

                const boxSize = 18;
                const speed = 1.0; 
                const animSpeed = 0.03;

                const COLORS = ['#22d3ee', '#a78bfa', '#fbbf24']; 
                const TARGET_YS = [beltY - 80, beltY - 40, beltY];

                const lastBox = state.boxes.length > 0 ? state.boxes[state.boxes.length - 1] : null;
                const safeToSpawn = !lastBox || (lastBox.x > 80); 

                if (safeToSpawn && Math.random() > 0.99) {
                    const typeIdx = Math.floor(Math.random() * 3);
                    state.boxes.push({
                        x: -20,
                        y: beltY - boxSize,
                        w: boxSize,
                        h: boxSize,
                        color: COLORS[typeIdx],
                        targetLane: typeIdx,
                        state: 'conveyor_in' 
                    });
                }

                ctx.fillStyle = 'rgba(255,255,255,0.1)';
                ctx.fillRect(0, beltY, inputEnd, 4);
                TARGET_YS.forEach(y => {
                    ctx.fillRect(outputStart, y + boxSize, w - outputStart, 4);
                });

                ctx.fillStyle = 'rgba(255,255,255,0.2)';
                const dashOffset = (time * 60) % 40; 
                for(let i=0; i<inputEnd; i+=40) {
                    const x = i + dashOffset;
                    if(x < inputEnd) ctx.fillRect(x, beltY, 4, 4);
                }
                TARGET_YS.forEach(y => {
                    for(let i=outputStart; i<w; i+=40) {
                        const x = i + dashOffset; 
                        if(x > outputStart) ctx.fillRect(x, y + boxSize, 4, 4);
                    }
                });

                const agent = state.agent;
                ctx.fillStyle = '#333';
                ctx.fillRect(agentX - 15, agentBaseY - 20, 30, 20); 

                const pivotX = agentX;
                const pivotY = agentBaseY - 20;

                let armX = pivotX;
                let armY = beltY - 60; 
                let grabberGap = 10;

                if (agent.state === 'idle') {
                    const target = state.boxes.find((b: any) => 
                        b.state === 'conveyor_in' && 
                        b.x > inputEnd - 60 && 
                        b.x < inputEnd
                    );
                    if (target) {
                        agent.state = 'reaching';
                        agent.targetBox = target;
                        agent.t = 0;
                    }
                }

                if (agent.state === 'reaching') {
                    agent.t += animSpeed;
                    const t = Math.min(1, agent.t);
                    const b = agent.targetBox;
                    if (b) {
                        if(b.x < inputEnd - 20) b.x += speed;
                        armX = pivotX + (b.x + b.w/2 - pivotX) * t;
                        armY = (pivotY - 80) + (b.y - (pivotY - 80)) * t;
                        if (t >= 1) { agent.state = 'grasping'; agent.t = 0; }
                    } else {
                        agent.state = 'idle'; // Reset if target gone
                    }
                } 
                else if (agent.state === 'grasping') {
                    agent.t += animSpeed * 2;
                    grabberGap = 10 * (1 - Math.min(1, agent.t));
                    if (agent.targetBox) {
                        armX = agent.targetBox.x + agent.targetBox.w/2;
                        armY = agent.targetBox.y;
                    }
                    if (agent.t >= 1) { agent.state = 'moving'; if(agent.targetBox) agent.targetBox.state = 'lifted'; agent.t = 0; }
                }
                else if (agent.state === 'moving') {
                    agent.t += animSpeed;
                    const t = Math.min(1, agent.t);
                    const b = agent.targetBox;
                    if (b) {
                        const targetY = TARGET_YS[b.targetLane];

                        const startX = inputEnd - 20;
                        const targetX = outputStart + 20;

                        armX = startX + (targetX - startX) * t;
                        const midY = Math.min(beltY, targetY) - 60;
                        armY = (1-t)*(1-t)*beltY + 2*(1-t)*t*midY + t*t*targetY;

                        grabberGap = 0;
                        b.x = armX - b.w/2;
                        b.y = armY;

                        if (t >= 1) { agent.state = 'releasing'; agent.t = 0; }
                    }
                }
                else if (agent.state === 'releasing') {
                    agent.t += animSpeed * 2;
                    const b = agent.targetBox;
                    if (b) {
                        armX = b.x + b.w/2;
                        armY = b.y;
                        grabberGap = 10 * Math.min(1, agent.t);

                        if (agent.t >= 1) {
                            b.state = 'conveyor_out';
                            b.y = TARGET_YS[b.targetLane];
                            agent.state = 'returning';
                            agent.targetBox = null;
                            agent.t = 0;
                        }
                    }
                }
                else if (agent.state === 'returning') {
                    agent.t += animSpeed;
                    const t = Math.min(1, agent.t);
                    const startX = outputStart + 20;
                    const startY = armY;
                    const targetX = pivotX;
                    const targetY = beltY - 60;
                    armX = startX + (targetX - startX) * t;
                    armY = startY + (targetY - startY) * t;
                    if (t >= 1) agent.state = 'idle';
                }
                else {
                    armX = pivotX + Math.sin(time * 2) * 5;
                    armY = beltY - 60 + Math.cos(time * 3) * 5;
                }

                ctx.strokeStyle = color;
                ctx.lineWidth = 2;
                ctx.beginPath();
                ctx.moveTo(pivotX, pivotY);
                const elbowX = (pivotX + armX) / 2 - 20; 
                const elbowY = Math.min(pivotY, armY) - 30;
                ctx.quadraticCurveTo(elbowX, elbowY, armX, armY);
                ctx.stroke();

                ctx.fillStyle = '#fff';
                ctx.beginPath(); ctx.arc(pivotX, pivotY, 3, 0, Math.PI*2); ctx.fill();
                ctx.beginPath(); ctx.arc(armX, armY, 3, 0, Math.PI*2); ctx.fill();

                ctx.save();
                ctx.translate(armX, armY);
                ctx.fillStyle = color;
                ctx.fillRect(-8 - grabberGap/2, -5, 4, 15);
                ctx.fillRect(4 + grabberGap/2, -5, 4, 15);
                ctx.restore();

                for (let i = state.boxes.length - 1; i >= 0; i--) {
                    const b = state.boxes[i];
                    if (b.state === 'conveyor_in') {
                        if (agent.targetBox !== b || agent.state === 'reaching') {
                             if (b.x < inputEnd - 20) b.x += speed; 
                        }
                    } else if (b.state === 'conveyor_out') {
                        b.x += speed;
                    }
                    if (b.x > w + 20) { state.boxes.splice(i, 1); continue; }

                    ctx.fillStyle = b.color;
                    ctx.strokeStyle = '#fff';
                    ctx.lineWidth = 1;
                    ctx.fillRect(b.x, b.y, b.w, b.h);
                    ctx.strokeRect(b.x, b.y, b.w, b.h);
                    ctx.fillStyle = 'rgba(0,0,0,0.3)';
                    ctx.fillRect(b.x + 2, b.y + 2, 4, 4);
                }
            } else if (mode === 'translation') {
                // Translation mode logic
                const colWidth = 140; 
                const numCols = 2; 
                const SNIPPETS = ["POST /api/v1/ingest", "{ id: '8f3a' }", "WARN: Latency", "Converting...", "0x4F3E21", "SELECT * FROM logs", "Processing...", "struct Node", "ERROR: Timeout", "> System.init()"];

                if (state.columns.length === 0) {
                    state.columns = Array.from({ length: numCols }, (_, i) => ({
                        x: 20 + i * (colWidth + 10),
                        y: Math.random() * h,
                        speed: 0.5 + Math.random() * 0.5,
                        items: Array.from({ length: 15 }, () => ({
                            text: SNIPPETS[Math.floor(Math.random() * SNIPPETS.length)],
                            y: 0 
                        }))
                    }));
                }

                const gridStartX = w * 0.55;
                const gridCols = 6; const gridRows = 8;
                const cellW = (w * 0.4) / gridCols; const cellH = h / gridRows;
                if (state.grid.length === 0) {
                    for(let i=0; i<gridCols*gridRows; i++) {
                        state.grid.push({
                            x: gridStartX + (i % gridCols) * cellW + cellW/2,
                            y: Math.floor(i / gridCols) * cellH + cellH/2,
                            filled: false, alpha: 0.2
                        });
                    }
                }

                ctx.font = '10px monospace';
                ctx.textAlign = 'left';

                state.columns.forEach((col: any) => {
                    col.y -= col.speed;
                    if (col.y < -300) col.y = h; 

                    col.items.forEach((item: any, i: number) => {
                        const yPos = col.y + i * 20;
                        const drawnY = yPos % (h + 300) - 50;

                        if (drawnY > -20 && drawnY < h + 20) {
                            const isScanned = Math.abs(drawnY - h/2) < 20;
                            ctx.fillStyle = isScanned ? '#fff' : 'rgba(255,255,255,0.3)';
                            if (isScanned) {
                                if (Math.random() > 0.98) {
                                    const empty = state.grid.filter((g: any) => !g.filled);
                                    if (empty.length > 0) {
                                        const t = empty[Math.floor(Math.random() * empty.length)];
                                        t.filled = true;
                                        state.particles.push({
                                            x: col.x + 80, y: drawnY,
                                            tx: t.x, ty: t.y,
                                            progress: 0, speed: 0.05,
                                            target: t
                                        });
                                    }
                                }
                            }
                            ctx.fillText(item.text, col.x, drawnY);
                        }
                    });
                });

                ctx.fillStyle = color;
                ctx.globalAlpha = 0.1;
                ctx.fillRect(0, h/2 - 20, w * 0.45, 40);
                ctx.globalAlpha = 0.8;
                ctx.fillRect(0, h/2, w * 0.45, 1);

                ctx.globalAlpha = 1;
                for (let i = state.particles.length - 1; i >= 0; i--) {
                    const p = state.particles[i];
                    p.progress += p.speed;
                    const t = p.progress;
                    const lx = p.x + (p.tx - p.x) * t;
                    const ly = p.y + (p.ty - p.y) * t;

                    ctx.fillStyle = color;
                    ctx.fillRect(lx - 2, ly - 2, 4, 4);

                    if (p.progress >= 1) {
                        p.target.alpha = 1.0;
                        state.particles.splice(i, 1);
                    }
                }

                state.grid.forEach((cell: any) => {
                    if (cell.filled) cell.alpha = Math.max(0.4, cell.alpha - 0.02);
                    else cell.alpha = 0.1;
                    const s = Math.min(cellW, cellH) * 0.6;
                    ctx.strokeStyle = color; ctx.globalAlpha = cell.alpha; ctx.lineWidth = 1;
                    ctx.strokeRect(cell.x - s/2, cell.y - s/2, s, s);
                    if (cell.filled) {
                        ctx.fillStyle = color; ctx.globalAlpha = cell.alpha * 0.6;
                        ctx.fillRect(cell.x - s/2 + 2, cell.y - s/2 + 2, s - 4, s - 4);
                        if (Math.random() > 0.995) cell.filled = false;
                    }
                });
            }

            ctx.globalAlpha = 1;
            frameId = requestAnimationFrame(render);
        };

        const observer = new ResizeObserver(() => { 
            // Debounce resize to prevent loop error
            window.requestAnimationFrame(() => resize()); 
        });
        observer.observe(container);

        // Initial setup
        resize();
        render();

        return () => {
            observer.disconnect();
            cancelAnimationFrame(frameId);
        };
    }, [mode, color]);

    return (
        <div ref={containerRef} className="w-full h-full relative overflow-hidden bg-[#0c0c0e]">
            <canvas ref={canvasRef} className="block absolute top-0 left-0" />
            <div className="absolute inset-0 pointer-events-none opacity-20" style={{ backgroundImage: 'linear-gradient(rgba(18, 16, 16, 0) 50%, rgba(0, 0, 0, 0.25) 50%), linear-gradient(90deg, rgba(255, 0, 0, 0.06), rgba(0, 255, 0, 0.02), rgba(0, 0, 255, 0.06))', backgroundSize: '100% 2px, 3px 100%' }} />
        </div>
    );
};

import React, { useEffect, useRef } from 'react';

interface SectionVisualizerProps {
    mode: 'search' | 'redaction' | 'logic' | 'core' | 'shield' | 'swarm' | 'predictive' | 'translation' | 'identity';
    color: string;
}

export const SectionVisualizer: React.FC<SectionVisualizerProps> = ({ mode, color }) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const containerRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        const canvas = canvasRef.current;
        const container = containerRef.current;
        if (!canvas || !container) return;

        const ctx = canvas.getContext('2d', { alpha: true });
        if (!ctx) return;

        let frameId: number;
        let time = 0;

        // --- HELPER: Polyfill for roundRect ---
        const drawRoundedRect = (x: number, y: number, w: number, h: number, r: number) => {
            if (ctx.roundRect) {
                ctx.beginPath();
                ctx.roundRect(x, y, w, h, r);
                return;
            }
            // Fallback for browsers without roundRect
            ctx.beginPath();
            ctx.moveTo(x + r, y);
            ctx.lineTo(x + w - r, y);
            ctx.quadraticCurveTo(x + w, y, x + w, y + r);
            ctx.lineTo(x + w, y + h - r);
            ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
            ctx.lineTo(x + r, y + h);
            ctx.quadraticCurveTo(x, y + h, x, y + h - r);
            ctx.lineTo(x, y + r);
            ctx.quadraticCurveTo(x, y, x + r, y);
            ctx.closePath();
        };

        // --- STATE MANAGEMENT ---
        const state: any = {
            width: 0,
            height: 0,
            particles: [],
            nodes: [],
            links: [], 
            grid: [],
            columns: [], 
            task: null, 
            agent: { state: 'idle', t: 0, heldBox: null, armHeight: 0, armExt: 0 },
            boxes: [], 
            stack: [],
            // Identity Mode (Strategic Nexus) State
            satellites: [],
            nexusPackets: [],
            systemLogs: [],
            logTimer: 0,
            orbitSpeed: 0.002,
            // Logic/Strategy Mode State
            packets: [],
            initializedMode: null
        };

        const init = (w: number, h: number) => {
            state.particles = [];
            state.nodes = [];
            state.links = [];
            state.grid = [];
            state.columns = [];
            state.task = null;
            state.boxes = [];
            state.stack = [];
            state.packets = [];
            state.agent = { state: 'idle', t: 0, heldBox: null, armHeight: 0, armExt: 0 };

            state.initializedMode = mode;

            if (mode === 'identity') {
                // Initialize "Strategic Nexus"
                // Satellites orbiting a central core
                const domains = [
                    { label: "LEGAL_CORPUS", r: 140, speed: 1.0 },
                    { label: "HISTORICAL_DATA", r: 190, speed: 0.8 },
                    { label: "FINANCIAL_MODELS", r: 230, speed: 0.6 },
                    { label: "TECH_STACK", r: 160, speed: -0.9 }, // Retrograde
                    { label: "HR_POLICIES", r: 210, speed: -0.7 }
                ];

                state.satellites = domains.map((d, i) => ({
                    ...d,
                    angle: (i / domains.length) * Math.PI * 2,
                    x: 0, y: 0 // Calculated in render
                }));

                state.nexusPackets = [];
                state.systemLogs = [
                    { text: "SYSTEM_READY", opacity: 1, type: 'info' }
                ];
                state.logTimer = 0;
            }
            else if (mode === 'search') {
                const particleCount = 80;
                for(let i=0; i<particleCount; i++) {
                    state.particles.push({
                        x: Math.random() * w,
                        y: Math.random() * h,
                        vx: 2 + Math.random() * 1.5,
                        vy: (Math.random() - 0.5) * 0.5,
                        targetLane: Math.floor(Math.random() * 5),
                        size: 0.5 + Math.random() * 0.5
                    });
                }
            }
            else if (mode === 'logic') {
                // STRATEGY BUILDER
                state.nodes.push({ id: 0, x: w * 0.15, y: h * 0.3, label: "DEMAND SPIKE", type: 'trigger', active: 0 });
                state.nodes.push({ id: 1, x: w * 0.15, y: h * 0.7, label: "INVENTORY LOW", type: 'trigger', active: 0 });
                state.nodes.push({ id: 2, x: w * 0.45, y: h * 0.5, label: "ALLOCATION LOGIC", type: 'process', active: 0 });
                state.nodes.push({ id: 3, x: w * 0.75, y: h * 0.25, label: "PRIORITY: RETAIL", type: 'action', active: 0 });
                state.nodes.push({ id: 4, x: w * 0.75, y: h * 0.75, label: "LIMIT WHOLESALE", type: 'action', active: 0 });
                state.links.push({ from: 0, to: 2 });
                state.links.push({ from: 1, to: 2 });
                state.links.push({ from: 2, to: 3 });
                state.links.push({ from: 2, to: 4 });
            }
            else if (mode === 'core') {
                // KNOWLEDGE TREE
                state.nodes.push({id:0, x: 0, y: 0, layer: 0});
                const layerCounts = [6, 12, 18];
                let idCounter = 1;
                for(let i=0; i<layerCounts[0]; i++) {
                    const angle = (i / layerCounts[0]) * Math.PI * 2;
                    state.nodes.push({
                        id: idCounter++,
                        x: Math.cos(angle) * 60,
                        y: Math.sin(angle) * 60,
                        layer: 1
                    });
                }
                for(let i=0; i<layerCounts[1]; i++) {
                    const angle = (i / layerCounts[1]) * Math.PI * 2 + 0.2;
                    state.nodes.push({
                        id: idCounter++,
                        x: Math.cos(angle) * 120,
                        y: Math.sin(angle) * 120,
                        layer: 2
                    });
                }
                for(let i=1; i<=layerCounts[0]; i++) {
                    state.links.push({from: 0, to: i});
                }
                for(let i=0; i<layerCounts[1]; i++) {
                    const targetNodeId = 1 + layerCounts[0] + i;
                    const sourceNodeId = 1 + Math.floor(i / 2);
                    if(state.nodes[targetNodeId] && state.nodes[sourceNodeId]) {
                        state.links.push({from: sourceNodeId, to: targetNodeId});
                    }
                }
            }
        };

        const resize = () => {
            const rect = container.getBoundingClientRect();
            if (rect.width === 0 || rect.height === 0) return;

            const dpr = window.devicePixelRatio || 1;

            canvas.width = rect.width * dpr;
            canvas.height = rect.height * dpr;

            canvas.style.width = `${rect.width}px`;
            canvas.style.height = `${rect.height}px`;

            ctx.scale(dpr, dpr);

            state.width = rect.width;
            state.height = rect.height;

            if (mode !== state.initializedMode || Math.abs(state.width - rect.width) > 10) {
                init(rect.width, rect.height);
            }
        };

        const render = () => {
            time += 0.01;
            const w = state.width;
            const h = state.height;
            const cx = w/2;
            const cy = h/2;

            ctx.clearRect(0, 0, w, h);

            if (mode === 'identity') {
                // --- STRATEGIC NEXUS (High-Fidelity) ---

                const centerX = w * 0.4; // Shifted left to make room for logs
                const centerY = h * 0.5;

                // 1. UPDATE SATELLITES
                state.satellites.forEach((sat: any) => {
                    sat.angle += state.orbitSpeed * sat.speed;
                    // Elliptical Orbit
                    sat.x = centerX + Math.cos(sat.angle) * sat.r;
                    sat.y = centerY + Math.sin(sat.angle) * (sat.r * 0.8); // 0.8 aspect ratio for depth
                });

                // 2. LOGIC ENGINE (Randomly trigger data flows)
                if (Math.random() > 0.96) {
                    const source = state.satellites[Math.floor(Math.random() * state.satellites.length)];
                    state.nexusPackets.push({
                        sx: source.x, sy: source.y,
                        tx: centerX, ty: centerY,
                        progress: 0,
                        speed: 0.02 + Math.random() * 0.02,
                        type: 'inbound', // Satellite -> Core
                        label: source.label
                    });
                }

                // 3. DRAW ORBITAL RINGS (Background)
                ctx.lineWidth = 1;
                state.satellites.forEach((sat: any) => {
                    ctx.beginPath();
                    ctx.ellipse(centerX, centerY, sat.r, sat.r * 0.8, 0, 0, Math.PI * 2);
                    ctx.strokeStyle = 'rgba(255, 255, 255, 0.03)';
                    ctx.stroke();
                });

                // 4. DRAW CONNECTIONS & PACKETS
                // We use curved lines (Bezier) for organic feel
                state.nexusPackets.forEach((p: any, i: number) => {
                    p.progress += p.speed;

                    // Bezier Control Point (creates an arc)
                    const midX = (p.sx + p.tx) / 2;
                    const midY = (p.sy + p.ty) / 2 - 20; // Arc upwards

                    // Calculate current position on Bezier
                    const t = p.progress;
                    const invT = 1 - t;
                    const curX = invT*invT*p.sx + 2*invT*t*midX + t*t*p.tx;
                    const curY = invT*invT*p.sy + 2*invT*t*midY + t*t*p.ty;

                    // Draw Trail
                    ctx.strokeStyle = `rgba(255, 255, 255, ${0.2 * (1-t)})`;
                    ctx.beginPath();
                    ctx.moveTo(p.sx, p.sy);
                    ctx.quadraticCurveTo(midX, midY, curX, curY);
                    ctx.stroke();

                    // Draw Head
                    ctx.fillStyle = color;
                    ctx.shadowColor = color; ctx.shadowBlur = 10;
                    ctx.beginPath(); ctx.arc(curX, curY, 2, 0, Math.PI*2); ctx.fill();
                    ctx.shadowBlur = 0;

                    if (p.progress >= 1) {
                        // Packet Hit Core -> Generate Log
                        if (p.type === 'inbound') {
                            const events = [
                                "CONTEXT_MATCH", "POLICY_CHECK", "RISK_ANALYSIS", "HISTORY_LOOKUP", "COMPLIANCE_SCAN"
                            ];
                            const event = events[Math.floor(Math.random() * events.length)];
                            const logText = `> ${event}: ${p.label.split('_')[0]}_ID_${Math.floor(Math.random()*1000)}`;

                            state.systemLogs.unshift({ text: logText, opacity: 1, type: 'process' });
                            if (state.systemLogs.length > 8) state.systemLogs.pop();
                        }
                        state.nexusPackets.splice(i, 1);
                    }
                });

                // 5. DRAW SATELLITES
                state.satellites.forEach((sat: any) => {
                    ctx.fillStyle = '#0c0c0e';
                    ctx.strokeStyle = 'rgba(255,255,255,0.2)';
                    ctx.lineWidth = 1;

                    ctx.beginPath(); ctx.arc(sat.x, sat.y, 4, 0, Math.PI*2); 
                    ctx.fill(); ctx.stroke();

                    // Tiny label
                    ctx.fillStyle = 'rgba(255,255,255,0.4)';
                    ctx.font = '8px monospace';
                    ctx.textAlign = 'center';
                    ctx.fillText(sat.label, sat.x, sat.y + 12);
                });

                // 6. CENTRAL CORE (The User / Enterprise)
                ctx.save();
                ctx.translate(centerX, centerY);

                // Outer Ring (Rotating)
                ctx.rotate(time * 0.2);
                ctx.strokeStyle = color;
                ctx.lineWidth = 1;
                ctx.setLineDash([5, 10]);
                ctx.beginPath(); ctx.arc(0, 0, 35, 0, Math.PI * 2); ctx.stroke();
                ctx.setLineDash([]);

                // Inner Ring (Counter-Rotating)
                ctx.rotate(-time * 0.4);
                ctx.strokeStyle = 'rgba(255,255,255,0.5)';
                ctx.beginPath(); ctx.arc(0, 0, 25, 0, Math.PI * 2); ctx.stroke();

                // Solid Core
                ctx.fillStyle = '#fff';
                ctx.beginPath(); ctx.arc(0, 0, 4, 0, Math.PI*2); ctx.fill();

                ctx.restore();

                // 7. SYSTEM LOG (Right Sidebar)
                const logX = w * 0.7;
                const logY = h * 0.25;

                ctx.fillStyle = 'rgba(255,255,255,0.05)';
                drawRoundedRect(logX, logY - 10, w * 0.25, h * 0.6, 8);
                // ctx.fill(); // Optional background

                ctx.font = '10px monospace';
                ctx.textAlign = 'left';

                // Header
                ctx.fillStyle = color;
                ctx.fillText("/// STRATEGIC_INTEL_FEED", logX + 10, logY + 10);
                ctx.fillStyle = 'rgba(255,255,255,0.2)';
                ctx.fillRect(logX + 10, logY + 20, w * 0.25 - 40, 1);

                // Entries
                state.systemLogs.forEach((log: any, i: number) => {
                    const y = logY + 40 + i * 20;
                    ctx.fillStyle = `rgba(255, 255, 255, ${log.opacity * 0.7})`;
                    ctx.fillText(log.text, logX + 10, y);

                    // Decay opacity slightly for older logs visual effect?
                    // actually keep them visible, just fade out the bottom one if we wanted
                });

                // Blinking Cursor at bottom of logs
                if (Math.floor(time * 2) % 2 === 0) {
                    ctx.fillStyle = color;
                    ctx.fillRect(logX + 10, logY + 40 + state.systemLogs.length * 20, 6, 12);
                }
            }
            else if (mode === 'search') {
                const processLine = w * 0.4;
                const laneCount = 5;
                const laneHeight = h / laneCount;

                ctx.lineWidth = 1;
                ctx.strokeStyle = 'rgba(255, 255, 255, 0.08)';
                for(let i=0; i<laneCount; i++) {
                    const ly = i * laneHeight + laneHeight/2;
                    ctx.beginPath(); ctx.moveTo(processLine, ly); ctx.lineTo(w, ly); ctx.stroke();
                }

                const scannerGlow = ctx.createLinearGradient(processLine, 0, processLine + 60, 0);
                scannerGlow.addColorStop(0, color);
                scannerGlow.addColorStop(1, 'transparent');
                ctx.fillStyle = scannerGlow;
                ctx.globalAlpha = 0.15;
                ctx.fillRect(processLine, 0, 60, h);

                ctx.fillStyle = color;
                ctx.globalAlpha = 0.8;
                ctx.fillRect(processLine, 0, 2, h);

                state.particles.forEach((p: any) => {
                    p.x += p.vx;
                    if (p.x < processLine) {
                        p.y += p.vy;
                        if (p.y < 0) p.y += h;
                        if (p.y > h) p.y -= h;
                        ctx.fillStyle = 'rgba(255, 255, 255, 0.4)';
                        ctx.globalAlpha = 0.6;
                        ctx.beginPath(); ctx.arc(p.x, p.y, p.size * 2, 0, Math.PI*2); ctx.fill();
                    } else {
                        const targetY = p.targetLane * laneHeight + laneHeight/2;
                        p.y += (targetY - p.y) * 0.15; 
                        p.x += 1.5; 
                        ctx.fillStyle = color;
                        ctx.globalAlpha = 1;
                        const packetWidth = 20 * p.size;
                        const packetHeight = 4;
                        ctx.shadowColor = color; ctx.shadowBlur = 10;
                        ctx.fillRect(p.x, p.y - packetHeight/2, packetWidth, packetHeight);
                        ctx.shadowBlur = 0;
                    }
                    if (p.x > w + 50) {
                        p.x = -20;
                        p.y = Math.random() * h;
                        p.vx = 2 + Math.random() * 1.5;
                        p.targetLane = Math.floor(Math.random() * laneCount);
                    }
                });
            }
            else if (mode === 'redaction') {
                const scanY = (time * 100) % (h + 100) - 50;
                // Add dummy particles if empty
                if (state.particles.length === 0) {
                    for(let i=0; i<50; i++) {
                        state.particles.push({x: Math.random()*w, y: Math.random()*h, w: 20+Math.random()*40, h: 6});
                    }
                }

                state.particles.forEach((p: any) => {
                    const dist = Math.abs(p.y - scanY);
                    if (dist < 50) {
                        ctx.fillStyle = color;
                        ctx.globalAlpha = 1 - (dist/50);
                        ctx.fillRect(p.x, p.y, p.w, p.h);
                    } else {
                        ctx.fillStyle = 'rgba(255,255,255,0.05)';
                        ctx.globalAlpha = 1;
                        ctx.fillRect(p.x, p.y, p.w, p.h);
                    }
                });
                ctx.fillStyle = '#fff';
                ctx.fillRect(0, scanY, w, 2);
            }
            else if (mode === 'logic') {
                // Spawn Packets
                if (Math.random() > 0.98) {
                    const startNodes = state.nodes.filter((n: any) => n.type === 'trigger');
                    if (startNodes.length > 0) {
                        const start = startNodes[Math.floor(Math.random() * startNodes.length)];
                        state.nodes.forEach((n: any) => { if(n.id === start.id) n.active = 1.0; });

                        // Find links from this start
                        const links = state.links.filter((l: any) => l.from === start.id);
                        links.forEach((l: any) => {
                            state.packets.push({
                                fromId: l.from, toId: l.to, progress: 0, speed: 0.02 + Math.random() * 0.01
                            });
                        });
                    }
                }

                // Draw Links
                ctx.lineWidth = 2;
                state.links.forEach((l: any) => {
                    const n1 = state.nodes.find((n: any) => n.id === l.from);
                    const n2 = state.nodes.find((n: any) => n.id === l.to);

                    if (n1 && n2) {
                        const grad = ctx.createLinearGradient(n1.x, n1.y, n2.x, n2.y);
                        grad.addColorStop(0, 'rgba(255,255,255,0.1)');
                        grad.addColorStop(1, 'rgba(255,255,255,0.05)');
                        ctx.strokeStyle = grad;

                        ctx.beginPath();
                        ctx.moveTo(n1.x, n1.y);
                        const midX = (n1.x + n2.x) / 2;
                        ctx.bezierCurveTo(midX, n1.y, midX, n2.y, n2.x, n2.y);
                        ctx.stroke();
                    }
                });

                // Draw Packets
                for (let i = state.packets.length - 1; i >= 0; i--) {
                    const p = state.packets[i];
                    p.progress += p.speed;

                    const n1 = state.nodes.find((n: any) => n.id === p.fromId);
                    const n2 = state.nodes.find((n: any) => n.id === p.toId);

                    if (n1 && n2) {
                        const midX = (n1.x + n2.x) / 2;
                        const t = p.progress;
                        const invT = 1 - t;

                        const x = invT*invT*invT*n1.x + 3*invT*invT*t*midX + 3*invT*t*t*midX + t*t*t*n2.x;
                        const y = invT*invT*invT*n1.y + 3*invT*invT*t*n1.y + 3*invT*t*t*n2.y + t*t*t*n2.y;

                        ctx.fillStyle = color;
                        ctx.shadowBlur = 10; ctx.shadowColor = color;
                        ctx.beginPath(); ctx.arc(x, y, 3, 0, Math.PI*2); ctx.fill();
                        ctx.shadowBlur = 0;

                        if (p.progress >= 1) {
                            n2.active = 1.0;
                            const nextLinks = state.links.filter((l: any) => l.from === n2.id);
                            nextLinks.forEach((l: any) => {
                                state.packets.push({ fromId: l.from, toId: l.to, progress: 0, speed: 0.02 });
                            });
                            state.packets.splice(i, 1);
                        }
                    }
                }

                // Draw Nodes
                state.nodes.forEach((n: any) => {
                    const isActive = n.active > 0.01;
                    if (n.active > 0) n.active *= 0.95;

                    ctx.save();
                    ctx.translate(n.x, n.y);

                    if (n.type === 'trigger') {
                        ctx.fillStyle = isActive ? color : '#1a1a1c';
                        ctx.strokeStyle = isActive ? '#fff' : 'rgba(255,255,255,0.2)';
                        ctx.beginPath(); ctx.moveTo(0, -20); ctx.lineTo(20, 0); ctx.lineTo(0, 20); ctx.lineTo(-20, 0); ctx.closePath();
                    } else if (n.type === 'process') {
                        ctx.fillStyle = isActive ? color : '#1a1a1c';
                        ctx.strokeStyle = isActive ? '#fff' : 'rgba(255,255,255,0.2)';
                        drawRoundedRect(-40, -20, 80, 40, 4);
                    } else {
                        ctx.fillStyle = isActive ? color : '#1a1a1c';
                        ctx.strokeStyle = isActive ? '#fff' : 'rgba(255,255,255,0.2)';
                        drawRoundedRect(-30, -15, 60, 30, 15);
                    }

                    ctx.globalAlpha = isActive ? 0.8 : 0.5;
                    ctx.fill();
                    ctx.globalAlpha = 1;
                    ctx.lineWidth = 1;
                    ctx.stroke();

                    ctx.fillStyle = '#fff';
                    ctx.font = '9px monospace';
                    ctx.textAlign = 'center';
                    ctx.textBaseline = 'middle';

                    const textW = ctx.measureText(n.label).width;
                    ctx.fillStyle = 'rgba(0,0,0,0.6)';
                    ctx.fillRect(-textW/2 - 4, 22, textW + 8, 14);
                    ctx.fillStyle = isActive ? color : '#888';
                    ctx.fillText(n.label, 0, 29);

                    ctx.restore();
                });
            }
            else if (mode === 'core') {
                if (Math.random() > 0.96) {
                    state.nodes[0].active = 1; 
                    const startLinks = state.links.filter((l: any) => l.from === 0);
                    if (startLinks.length > 0) {
                        const startLink = startLinks[Math.floor(Math.random() * startLinks.length)];
                        state.particles.push({
                            linkIdx: state.links.indexOf(startLink),
                            t: 0,
                            speed: 0.08
                        });
                    }
                }

                ctx.translate(cx, cy);
                ctx.rotate(time * 0.05);

                ctx.strokeStyle = 'rgba(255,255,255,0.08)';
                ctx.lineWidth = 1;
                ctx.beginPath();
                state.links.forEach((l: any) => {
                    const n1 = state.nodes[l.from];
                    const n2 = state.nodes[l.to];
                    if (n1 && n2) {
                        ctx.moveTo(n1.x, n1.y);
                        ctx.lineTo(n2.x, n2.y);
                    }
                });
                ctx.stroke();

                state.nodes.forEach((n:any) => {
                    if (n.active > 0) {
                        ctx.fillStyle = color;
                        ctx.shadowBlur = 10 * n.active;
                        ctx.shadowColor = color;
                        n.active -= 0.05;
                    } else {
                        ctx.fillStyle = n.layer === 0 ? color : 'rgba(255,255,255,0.3)';
                        ctx.shadowBlur = 0;
                    }
                    const size = n.layer === 0 ? 4 : 2;
                    ctx.beginPath(); ctx.arc(n.x, n.y, size, 0, Math.PI*2); ctx.fill();
                    ctx.shadowBlur = 0;
                });

                for(let i=state.particles.length-1; i>=0; i--) {
                    const p = state.particles[i];
                    p.t += p.speed;
                    const link = state.links[p.linkIdx];
                    if (!link) { state.particles.splice(i,1); continue; }

                    const n1 = state.nodes[link.from];
                    const n2 = state.nodes[link.to];

                    if (n1 && n2) {
                        const currX = n1.x + (n2.x - n1.x) * p.t;
                        const currY = n1.y + (n2.y - n1.y) * p.t;
                        ctx.fillStyle = '#fff';
                        ctx.shadowBlur = 5; ctx.shadowColor = '#fff';
                        ctx.fillRect(currX-1.5, currY-1.5, 3, 3);
                        ctx.shadowBlur = 0;
                        if (p.t >= 1) {
                            n2.active = 1;
                            // Propagate
                            if (n2.layer < 3 && Math.random() > 0.3) {
                                const nextLinks = state.links
                                    .map((l: any, idx: number) => ({...l, idx}))
                                    .filter((l: any) => l.from === link.to);

                                if (nextLinks.length > 0) {
                                    const nextL = nextLinks[Math.floor(Math.random() * nextLinks.length)];
                                    state.particles.push({ linkIdx: nextL.idx, t: 0, speed: 0.08 });
                                }
                            }
                            state.particles.splice(i, 1);
                        }
                    } else {
                        state.particles.splice(i, 1);
                    }
                }
                ctx.rotate(-time * 0.05);
                ctx.translate(-cx, -cy);
            }
            // ... (Other modes: swarm, translation - omitted for brevity as they weren't reported broken, but pattern holds)
            else if (mode === 'swarm') {
                // (Keeping swarm logic intact as it was stable)
                // ... (Swarm logic from original file) ...
                // Re-inserted swarm logic for completeness to avoid regression
                const beltY = h * 0.65; 
                const inputEnd = w * 0.45;
                const outputStart = w * 0.55;
                const agentX = w * 0.5;
                const agentBaseY = beltY + 40;

                const boxSize = 18;
                const speed = 1.0; 
                const animSpeed = 0.03;

                const COLORS = ['#22d3ee', '#a78bfa', '#fbbf24']; 
                const TARGET_YS = [beltY - 80, beltY - 40, beltY];

                const lastBox = state.boxes.length > 0 ? state.boxes[state.boxes.length - 1] : null;
                const safeToSpawn = !lastBox || (lastBox.x > 80); 

                if (safeToSpawn && Math.random() > 0.99) {
                    const typeIdx = Math.floor(Math.random() * 3);
                    state.boxes.push({
                        x: -20,
                        y: beltY - boxSize,
                        w: boxSize,
                        h: boxSize,
                        color: COLORS[typeIdx],
                        targetLane: typeIdx,
                        state: 'conveyor_in' 
                    });
                }

                ctx.fillStyle = 'rgba(255,255,255,0.1)';
                ctx.fillRect(0, beltY, inputEnd, 4);
                TARGET_YS.forEach(y => {
                    ctx.fillRect(outputStart, y + boxSize, w - outputStart, 4);
                });

                ctx.fillStyle = 'rgba(255,255,255,0.2)';
                const dashOffset = (time * 60) % 40; 
                for(let i=0; i<inputEnd; i+=40) {
                    const x = i + dashOffset;
                    if(x < inputEnd) ctx.fillRect(x, beltY, 4, 4);
                }
                TARGET_YS.forEach(y => {
                    for(let i=outputStart; i<w; i+=40) {
                        const x = i + dashOffset; 
                        if(x > outputStart) ctx.fillRect(x, y + boxSize, 4, 4);
                    }
                });

                const agent = state.agent;
                ctx.fillStyle = '#333';
                ctx.fillRect(agentX - 15, agentBaseY - 20, 30, 20); 

                const pivotX = agentX;
                const pivotY = agentBaseY - 20;

                let armX = pivotX;
                let armY = beltY - 60; 
                let grabberGap = 10;

                if (agent.state === 'idle') {
                    const target = state.boxes.find((b: any) => 
                        b.state === 'conveyor_in' && 
                        b.x > inputEnd - 60 && 
                        b.x < inputEnd
                    );
                    if (target) {
                        agent.state = 'reaching';
                        agent.targetBox = target;
                        agent.t = 0;
                    }
                }

                if (agent.state === 'reaching') {
                    agent.t += animSpeed;
                    const t = Math.min(1, agent.t);
                    const b = agent.targetBox;
                    if (b) {
                        if(b.x < inputEnd - 20) b.x += speed;
                        armX = pivotX + (b.x + b.w/2 - pivotX) * t;
                        armY = (pivotY - 80) + (b.y - (pivotY - 80)) * t;
                        if (t >= 1) { agent.state = 'grasping'; agent.t = 0; }
                    } else {
                        agent.state = 'idle'; // Reset if target gone
                    }
                } 
                else if (agent.state === 'grasping') {
                    agent.t += animSpeed * 2;
                    grabberGap = 10 * (1 - Math.min(1, agent.t));
                    if (agent.targetBox) {
                        armX = agent.targetBox.x + agent.targetBox.w/2;
                        armY = agent.targetBox.y;
                    }
                    if (agent.t >= 1) { agent.state = 'moving'; if(agent.targetBox) agent.targetBox.state = 'lifted'; agent.t = 0; }
                }
                else if (agent.state === 'moving') {
                    agent.t += animSpeed;
                    const t = Math.min(1, agent.t);
                    const b = agent.targetBox;
                    if (b) {
                        const targetY = TARGET_YS[b.targetLane];

                        const startX = inputEnd - 20;
                        const targetX = outputStart + 20;

                        armX = startX + (targetX - startX) * t;
                        const midY = Math.min(beltY, targetY) - 60;
                        armY = (1-t)*(1-t)*beltY + 2*(1-t)*t*midY + t*t*targetY;

                        grabberGap = 0;
                        b.x = armX - b.w/2;
                        b.y = armY;

                        if (t >= 1) { agent.state = 'releasing'; agent.t = 0; }
                    }
                }
                else if (agent.state === 'releasing') {
                    agent.t += animSpeed * 2;
                    const b = agent.targetBox;
                    if (b) {
                        armX = b.x + b.w/2;
                        armY = b.y;
                        grabberGap = 10 * Math.min(1, agent.t);

                        if (agent.t >= 1) {
                            b.state = 'conveyor_out';
                            b.y = TARGET_YS[b.targetLane];
                            agent.state = 'returning';
                            agent.targetBox = null;
                            agent.t = 0;
                        }
                    }
                }
                else if (agent.state === 'returning') {
                    agent.t += animSpeed;
                    const t = Math.min(1, agent.t);
                    const startX = outputStart + 20;
                    const startY = armY;
                    const targetX = pivotX;
                    const targetY = beltY - 60;
                    armX = startX + (targetX - startX) * t;
                    armY = startY + (targetY - startY) * t;
                    if (t >= 1) agent.state = 'idle';
                }
                else {
                    armX = pivotX + Math.sin(time * 2) * 5;
                    armY = beltY - 60 + Math.cos(time * 3) * 5;
                }

                ctx.strokeStyle = color;
                ctx.lineWidth = 2;
                ctx.beginPath();
                ctx.moveTo(pivotX, pivotY);
                const elbowX = (pivotX + armX) / 2 - 20; 
                const elbowY = Math.min(pivotY, armY) - 30;
                ctx.quadraticCurveTo(elbowX, elbowY, armX, armY);
                ctx.stroke();

                ctx.fillStyle = '#fff';
                ctx.beginPath(); ctx.arc(pivotX, pivotY, 3, 0, Math.PI*2); ctx.fill();
                ctx.beginPath(); ctx.arc(armX, armY, 3, 0, Math.PI*2); ctx.fill();

                ctx.save();
                ctx.translate(armX, armY);
                ctx.fillStyle = color;
                ctx.fillRect(-8 - grabberGap/2, -5, 4, 15);
                ctx.fillRect(4 + grabberGap/2, -5, 4, 15);
                ctx.restore();

                for (let i = state.boxes.length - 1; i >= 0; i--) {
                    const b = state.boxes[i];
                    if (b.state === 'conveyor_in') {
                        if (agent.targetBox !== b || agent.state === 'reaching') {
                             if (b.x < inputEnd - 20) b.x += speed; 
                        }
                    } else if (b.state === 'conveyor_out') {
                        b.x += speed;
                    }
                    if (b.x > w + 20) { state.boxes.splice(i, 1); continue; }

                    ctx.fillStyle = b.color;
                    ctx.strokeStyle = '#fff';
                    ctx.lineWidth = 1;
                    ctx.fillRect(b.x, b.y, b.w, b.h);
                    ctx.strokeRect(b.x, b.y, b.w, b.h);
                    ctx.fillStyle = 'rgba(0,0,0,0.3)';
                    ctx.fillRect(b.x + 2, b.y + 2, 4, 4);
                }
            } else if (mode === 'translation') {
                // Translation mode logic
                const colWidth = 140; 
                const numCols = 2; 
                const SNIPPETS = ["POST /api/v1/ingest", "{ id: '8f3a' }", "WARN: Latency", "Converting...", "0x4F3E21", "SELECT * FROM logs", "Processing...", "struct Node", "ERROR: Timeout", "> System.init()"];

                if (state.columns.length === 0) {
                    state.columns = Array.from({ length: numCols }, (_, i) => ({
                        x: 20 + i * (colWidth + 10),
                        y: Math.random() * h,
                        speed: 0.5 + Math.random() * 0.5,
                        items: Array.from({ length: 15 }, () => ({
                            text: SNIPPETS[Math.floor(Math.random() * SNIPPETS.length)],
                            y: 0 
                        }))
                    }));
                }

                const gridStartX = w * 0.55;
                const gridCols = 6; const gridRows = 8;
                const cellW = (w * 0.4) / gridCols; const cellH = h / gridRows;
                if (state.grid.length === 0) {
                    for(let i=0; i<gridCols*gridRows; i++) {
                        state.grid.push({
                            x: gridStartX + (i % gridCols) * cellW + cellW/2,
                            y: Math.floor(i / gridCols) * cellH + cellH/2,
                            filled: false, alpha: 0.2
                        });
                    }
                }

                ctx.font = '10px monospace';
                ctx.textAlign = 'left';

                state.columns.forEach((col: any) => {
                    col.y -= col.speed;
                    if (col.y < -300) col.y = h; 

                    col.items.forEach((item: any, i: number) => {
                        const yPos = col.y + i * 20;
                        const drawnY = yPos % (h + 300) - 50;

                        if (drawnY > -20 && drawnY < h + 20) {
                            const isScanned = Math.abs(drawnY - h/2) < 20;
                            ctx.fillStyle = isScanned ? '#fff' : 'rgba(255,255,255,0.3)';
                            if (isScanned) {
                                if (Math.random() > 0.98) {
                                    const empty = state.grid.filter((g: any) => !g.filled);
                                    if (empty.length > 0) {
                                        const t = empty[Math.floor(Math.random() * empty.length)];
                                        t.filled = true;
                                        state.particles.push({
                                            x: col.x + 80, y: drawnY,
                                            tx: t.x, ty: t.y,
                                            progress: 0, speed: 0.05,
                                            target: t
                                        });
                                    }
                                }
                            }
                            ctx.fillText(item.text, col.x, drawnY);
                        }
                    });
                });

                ctx.fillStyle = color;
                ctx.globalAlpha = 0.1;
                ctx.fillRect(0, h/2 - 20, w * 0.45, 40);
                ctx.globalAlpha = 0.8;
                ctx.fillRect(0, h/2, w * 0.45, 1);

                ctx.globalAlpha = 1;
                for (let i = state.particles.length - 1; i >= 0; i--) {
                    const p = state.particles[i];
                    p.progress += p.speed;
                    const t = p.progress;
                    const lx = p.x + (p.tx - p.x) * t;
                    const ly = p.y + (p.ty - p.y) * t;

                    ctx.fillStyle = color;
                    ctx.fillRect(lx - 2, ly - 2, 4, 4);

                    if (p.progress >= 1) {
                        p.target.alpha = 1.0;
                        state.particles.splice(i, 1);
                    }
                }

                state.grid.forEach((cell: any) => {
                    if (cell.filled) cell.alpha = Math.max(0.4, cell.alpha - 0.02);
                    else cell.alpha = 0.1;
                    const s = Math.min(cellW, cellH) * 0.6;
                    ctx.strokeStyle = color; ctx.globalAlpha = cell.alpha; ctx.lineWidth = 1;
                    ctx.strokeRect(cell.x - s/2, cell.y - s/2, s, s);
                    if (cell.filled) {
                        ctx.fillStyle = color; ctx.globalAlpha = cell.alpha * 0.6;
                        ctx.fillRect(cell.x - s/2 + 2, cell.y - s/2 + 2, s - 4, s - 4);
                        if (Math.random() > 0.995) cell.filled = false;
                    }
                });
            }

            ctx.globalAlpha = 1;
            frameId = requestAnimationFrame(render);
        };

        const observer = new ResizeObserver(() => { 
            // Debounce resize to prevent loop error
            window.requestAnimationFrame(() => resize()); 
        });
        observer.observe(container);

        // Initial setup
        resize();
        render();

        return () => {
            observer.disconnect();
            cancelAnimationFrame(frameId);
        };
    }, [mode, color]);

    return (
        <div ref={containerRef} className="w-full h-full relative overflow-hidden bg-[#0c0c0e]">
            <canvas ref={canvasRef} className="block absolute top-0 left-0" />
            <div className="absolute inset-0 pointer-events-none opacity-20" style={{ backgroundImage: 'linear-gradient(rgba(18, 16, 16, 0) 50%, rgba(0, 0, 0, 0.25) 50%), linear-gradient(90deg, rgba(255, 0, 0, 0.06), rgba(0, 255, 0, 0.02), rgba(0, 0, 255, 0.06))', backgroundSize: '100% 2px, 3px 100%' }} />
        </div>
    );
};

import React, { useEffect, useRef } from 'react';

interface SectionVisualizerProps {
    mode: 'search' | 'redaction' | 'logic' | 'core' | 'shield' | 'swarm' | 'predictive' | 'translation' | 'identity';
    color: string;
}

export const SectionVisualizer: React.FC<SectionVisualizerProps> = ({ mode, color }) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const containerRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        const canvas = canvasRef.current;
        const container = containerRef.current;
        if (!canvas || !container) return;

        const ctx = canvas.getContext('2d', { alpha: true });
        if (!ctx) return;

        let frameId: number;
        let time = 0;

        // --- HELPER: Polyfill for roundRect ---
        const drawRoundedRect = (x: number, y: number, w: number, h: number, r: number) => {
            if (ctx.roundRect) {
                ctx.beginPath();
                ctx.roundRect(x, y, w, h, r);
                return;
            }
            // Fallback for browsers without roundRect
            ctx.beginPath();
            ctx.moveTo(x + r, y);
            ctx.lineTo(x + w - r, y);
            ctx.quadraticCurveTo(x + w, y, x + w, y + r);
            ctx.lineTo(x + w, y + h - r);
            ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
            ctx.lineTo(x + r, y + h);
            ctx.quadraticCurveTo(x, y + h, x, y + h - r);
            ctx.lineTo(x, y + r);
            ctx.quadraticCurveTo(x, y, x + r, y);
            ctx.closePath();
        };

        // --- STATE MANAGEMENT ---
        const state: any = {
            width: 0,
            height: 0,
            particles: [],
            nodes: [],
            links: [], 
            grid: [],
            columns: [], 
            task: null, 
            agent: { state: 'idle', t: 0, heldBox: null, armHeight: 0, armExt: 0 },
            boxes: [], 
            stack: [],
            // Identity Mode (Flashcard) State
            cards: [],
            activeCardIndex: 0,
            swipeProgress: 0, // 0 to 1
            swipeDirection: 1, // 1 = right, -1 = left
            cardState: 'reading', // reading, swiping
            cardTimer: 0,
            // Logic/Strategy Mode State
            packets: [],
            initializedMode: null
        };

        const init = (w: number, h: number) => {
            state.particles = [];
            state.nodes = [];
            state.links = [];
            state.grid = [];
            state.columns = [];
            state.task = null;
            state.boxes = [];
            state.stack = [];
            state.packets = [];
            state.agent = { state: 'idle', t: 0, heldBox: null, armHeight: 0, armExt: 0 };

            state.initializedMode = mode;

            if (mode === 'identity') {
                // Initialize Flashcards
                state.cards = [
                    { category: "POLICY_UPDATE", title: "Data Retention", text: "Purge cycles set to 90 days.", color: "#3b82f6" },
                    { category: "WORKFLOW", title: "Approval Chain", text: "New vendor requires VP sign-off.", color: "#10b981" },
                    { category: "COMPLIANCE", title: "PII Detection", text: "Filter updated for EU-West-1.", color: "#f59e0b" },
                    { category: "TRAINING", title: "Phishing Alert", text: "Report suspicious email headers.", color: "#ef4444" },
                    { category: "STRATEGY", title: "Q3 Targets", text: "Focus on retention metrics.", color: "#8b5cf6" }
                ];
                state.activeCardIndex = 0;
                state.cardState = 'reading';
                state.cardTimer = 0;
                state.swipeProgress = 0;
            }
            else if (mode === 'search') {
                const particleCount = 80;
                for(let i=0; i<particleCount; i++) {
                    state.particles.push({
                        x: Math.random() * w,
                        y: Math.random() * h,
                        vx: 2 + Math.random() * 1.5,
                        vy: (Math.random() - 0.5) * 0.5,
                        targetLane: Math.floor(Math.random() * 5),
                        size: 0.5 + Math.random() * 0.5
                    });
                }
            }
            else if (mode === 'logic') {
                // STRATEGY BUILDER
                state.nodes.push({ id: 0, x: w * 0.15, y: h * 0.3, label: "DEMAND SPIKE", type: 'trigger', active: 0 });
                state.nodes.push({ id: 1, x: w * 0.15, y: h * 0.7, label: "INVENTORY LOW", type: 'trigger', active: 0 });
                state.nodes.push({ id: 2, x: w * 0.45, y: h * 0.5, label: "ALLOCATION LOGIC", type: 'process', active: 0 });
                state.nodes.push({ id: 3, x: w * 0.75, y: h * 0.25, label: "PRIORITY: RETAIL", type: 'action', active: 0 });
                state.nodes.push({ id: 4, x: w * 0.75, y: h * 0.75, label: "LIMIT WHOLESALE", type: 'action', active: 0 });
                state.links.push({ from: 0, to: 2 });
                state.links.push({ from: 1, to: 2 });
                state.links.push({ from: 2, to: 3 });
                state.links.push({ from: 2, to: 4 });
            }
            else if (mode === 'core') {
                // KNOWLEDGE TREE
                state.nodes.push({id:0, x: 0, y: 0, layer: 0});
                const layerCounts = [6, 12, 18];
                let idCounter = 1;
                for(let i=0; i<layerCounts[0]; i++) {
                    const angle = (i / layerCounts[0]) * Math.PI * 2;
                    state.nodes.push({
                        id: idCounter++,
                        x: Math.cos(angle) * 60,
                        y: Math.sin(angle) * 60,
                        layer: 1
                    });
                }
                for(let i=0; i<layerCounts[1]; i++) {
                    const angle = (i / layerCounts[1]) * Math.PI * 2 + 0.2;
                    state.nodes.push({
                        id: idCounter++,
                        x: Math.cos(angle) * 120,
                        y: Math.sin(angle) * 120,
                        layer: 2
                    });
                }
                for(let i=1; i<=layerCounts[0]; i++) {
                    state.links.push({from: 0, to: i});
                }
                for(let i=0; i<layerCounts[1]; i++) {
                    const targetNodeId = 1 + layerCounts[0] + i;
                    const sourceNodeId = 1 + Math.floor(i / 2);
                    if(state.nodes[targetNodeId] && state.nodes[sourceNodeId]) {
                        state.links.push({from: sourceNodeId, to: targetNodeId});
                    }
                }
            }
        };

        const resize = () => {
            const rect = container.getBoundingClientRect();
            if (rect.width === 0 || rect.height === 0) return;

            const dpr = window.devicePixelRatio || 1;

            canvas.width = rect.width * dpr;
            canvas.height = rect.height * dpr;

            canvas.style.width = `${rect.width}px`;
            canvas.style.height = `${rect.height}px`;

            ctx.scale(dpr, dpr);

            state.width = rect.width;
            state.height = rect.height;

            if (mode !== state.initializedMode || Math.abs(state.width - rect.width) > 10) {
                init(rect.width, rect.height);
            }
        };

        const render = () => {
            time += 0.01;
            const w = state.width;
            const h = state.height;
            const cx = w/2;
            const cy = h/2;

            ctx.clearRect(0, 0, w, h);

            if (mode === 'identity') {
                // --- FLASHCARD ENGINE ---

                // Logic
                if (state.cardState === 'reading') {
                    state.cardTimer++;
                    if (state.cardTimer > 180) { // 3 seconds read time
                        state.cardState = 'swiping';
                        state.swipeDirection = Math.random() > 0.5 ? 1 : -1;
                    }
                } else if (state.cardState === 'swiping') {
                    state.swipeProgress += 0.04;
                    if (state.swipeProgress >= 1.5) { // Gone off screen
                        state.cardState = 'reading';
                        state.cardTimer = 0;
                        state.swipeProgress = 0;
                        state.activeCardIndex = (state.activeCardIndex + 1) % state.cards.length;
                    }
                }

                // Drawing Configuration
                const cardW = 180;
                const cardH = 240;

                // Draw Background Stack (3 cards)
                for(let i=3; i>0; i--) {
                    const idx = (state.activeCardIndex + i) % state.cards.length;
                    const card = state.cards[idx];

                    const offset = i * 4;
                    const scale = 1 - (i * 0.05);
                    const alpha = 1 - (i * 0.2);

                    ctx.save();
                    ctx.translate(cx, cy + offset);
                    ctx.scale(scale, scale);
                    ctx.globalAlpha = alpha * 0.5;

                    // Card Body
                    ctx.fillStyle = '#1a1a1c';
                    ctx.shadowBlur = 10; ctx.shadowColor = 'rgba(0,0,0,0.5)';
                    drawRoundedRect(-cardW/2, -cardH/2, cardW, cardH, 12);
                    ctx.fill();

                    // Top Bar
                    ctx.fillStyle = card.color;
                    ctx.beginPath();
                    // Clip top rounded part manually or just draw a rect if simple
                    // Simple top bar
                    drawRoundedRect(-cardW/2, -cardH/2, cardW, 6, 4);
                    ctx.fill();

                    ctx.restore();
                }

                // Draw Active Card
                const activeCard = state.cards[state.activeCardIndex];

                let activeX = cx;
                let activeY = cy;
                let activeRot = 0;
                let activeAlpha = 1;

                if (state.cardState === 'swiping') {
                    const t = state.swipeProgress;
                    activeX = cx + (t * w * 0.8 * state.swipeDirection);
                    activeY = cy + Math.abs(Math.sin(t * Math.PI)) * 50;
                    activeRot = t * 0.2 * state.swipeDirection;
                    activeAlpha = 1 - Math.min(1, t * 0.8);
                }

                ctx.save();
                ctx.translate(activeX, activeY);
                ctx.rotate(activeRot);
                ctx.globalAlpha = activeAlpha;

                // Card Body
                ctx.fillStyle = '#1a1a1c';
                ctx.strokeStyle = 'rgba(255,255,255,0.1)';
                ctx.lineWidth = 1;
                ctx.shadowBlur = 20; ctx.shadowColor = 'rgba(0,0,0,0.5)';
                drawRoundedRect(-cardW/2, -cardH/2, cardW, cardH, 12);
                ctx.fill();
                ctx.stroke();
                ctx.shadowBlur = 0;

                // Color Bar
                ctx.fillStyle = activeCard.color;
                // Top rounded rect
                ctx.beginPath();
                ctx.moveTo(-cardW/2 + 12, -cardH/2);
                ctx.lineTo(cardW/2 - 12, -cardH/2);
                ctx.quadraticCurveTo(cardW/2, -cardH/2, cardW/2, -cardH/2 + 12);
                ctx.lineTo(cardW/2, -cardH/2 + 20);
                ctx.lineTo(-cardW/2, -cardH/2 + 20);
                ctx.lineTo(-cardW/2, -cardH/2 + 12);
                ctx.quadraticCurveTo(-cardW/2, -cardH/2, -cardW/2 + 12, -cardH/2);
                ctx.fill();

                // Text Content
                ctx.textAlign = 'center';
                ctx.fillStyle = activeCard.color;
                ctx.font = 'bold 9px monospace';
                ctx.fillText(activeCard.category, 0, -cardH/2 + 35);

                ctx.fillStyle = '#fff';
                ctx.font = 'bold 16px sans-serif';
                // Simple wrap for title if needed, but keeping short
                ctx.fillText(activeCard.title, 0, -20);

                ctx.fillStyle = 'rgba(255,255,255,0.6)';
                ctx.font = '11px sans-serif';
                const words = activeCard.text.split(' ');
                let line = "";
                let ly = 10;
                for(let i=0; i<words.length; i++) {
                    const testLine = line + words[i] + " ";
                    if (ctx.measureText(testLine).width > cardW - 30) {
                        ctx.fillText(line, 0, ly);
                        line = words[i] + " ";
                        ly += 16;
                    } else {
                        line = testLine;
                    }
                }
                ctx.fillText(line, 0, ly);

                // Progress Bar at bottom
                if (state.cardState === 'reading') {
                    const p = state.cardTimer / 180;
                    ctx.fillStyle = 'rgba(255,255,255,0.1)';
                    ctx.fillRect(-cardW/2 + 20, cardH/2 - 20, cardW - 40, 4);
                    ctx.fillStyle = activeCard.color;
                    ctx.fillRect(-cardW/2 + 20, cardH/2 - 20, (cardW - 40) * p, 4);
                }

                ctx.restore();
            }
            else if (mode === 'search') {
                const processLine = w * 0.4;
                const laneCount = 5;
                const laneHeight = h / laneCount;

                ctx.lineWidth = 1;
                ctx.strokeStyle = 'rgba(255, 255, 255, 0.08)';
                for(let i=0; i<laneCount; i++) {
                    const ly = i * laneHeight + laneHeight/2;
                    ctx.beginPath(); ctx.moveTo(processLine, ly); ctx.lineTo(w, ly); ctx.stroke();
                }

                const scannerGlow = ctx.createLinearGradient(processLine, 0, processLine + 60, 0);
                scannerGlow.addColorStop(0, color);
                scannerGlow.addColorStop(1, 'transparent');
                ctx.fillStyle = scannerGlow;
                ctx.globalAlpha = 0.15;
                ctx.fillRect(processLine, 0, 60, h);

                ctx.fillStyle = color;
                ctx.globalAlpha = 0.8;
                ctx.fillRect(processLine, 0, 2, h);

                state.particles.forEach((p: any) => {
                    p.x += p.vx;
                    if (p.x < processLine) {
                        p.y += p.vy;
                        if (p.y < 0) p.y += h;
                        if (p.y > h) p.y -= h;
                        ctx.fillStyle = 'rgba(255, 255, 255, 0.4)';
                        ctx.globalAlpha = 0.6;
                        ctx.beginPath(); ctx.arc(p.x, p.y, p.size * 2, 0, Math.PI*2); ctx.fill();
                    } else {
                        const targetY = p.targetLane * laneHeight + laneHeight/2;
                        p.y += (targetY - p.y) * 0.15; 
                        p.x += 1.5; 
                        ctx.fillStyle = color;
                        ctx.globalAlpha = 1;
                        const packetWidth = 20 * p.size;
                        const packetHeight = 4;
                        ctx.shadowColor = color; ctx.shadowBlur = 10;
                        ctx.fillRect(p.x, p.y - packetHeight/2, packetWidth, packetHeight);
                        ctx.shadowBlur = 0;
                    }
                    if (p.x > w + 50) {
                        p.x = -20;
                        p.y = Math.random() * h;
                        p.vx = 2 + Math.random() * 1.5;
                        p.targetLane = Math.floor(Math.random() * laneCount);
                    }
                });
            }
            else if (mode === 'redaction') {
                const scanY = (time * 100) % (h + 100) - 50;
                // Add dummy particles if empty
                if (state.particles.length === 0) {
                    for(let i=0; i<50; i++) {
                        state.particles.push({x: Math.random()*w, y: Math.random()*h, w: 20+Math.random()*40, h: 6});
                    }
                }

                state.particles.forEach((p: any) => {
                    const dist = Math.abs(p.y - scanY);
                    if (dist < 50) {
                        ctx.fillStyle = color;
                        ctx.globalAlpha = 1 - (dist/50);
                        ctx.fillRect(p.x, p.y, p.w, p.h);
                    } else {
                        ctx.fillStyle = 'rgba(255,255,255,0.05)';
                        ctx.globalAlpha = 1;
                        ctx.fillRect(p.x, p.y, p.w, p.h);
                    }
                });
                ctx.fillStyle = '#fff';
                ctx.fillRect(0, scanY, w, 2);
            }
            else if (mode === 'logic') {
                // Spawn Packets
                if (Math.random() > 0.98) {
                    const startNodes = state.nodes.filter((n: any) => n.type === 'trigger');
                    if (startNodes.length > 0) {
                        const start = startNodes[Math.floor(Math.random() * startNodes.length)];
                        state.nodes.forEach((n: any) => { if(n.id === start.id) n.active = 1.0; });

                        // Find links from this start
                        const links = state.links.filter((l: any) => l.from === start.id);
                        links.forEach((l: any) => {
                            state.packets.push({
                                fromId: l.from, toId: l.to, progress: 0, speed: 0.02 + Math.random() * 0.01
                            });
                        });
                    }
                }

                // Draw Links
                ctx.lineWidth = 2;
                state.links.forEach((l: any) => {
                    const n1 = state.nodes.find((n: any) => n.id === l.from);
                    const n2 = state.nodes.find((n: any) => n.id === l.to);

                    if (n1 && n2) {
                        const grad = ctx.createLinearGradient(n1.x, n1.y, n2.x, n2.y);
                        grad.addColorStop(0, 'rgba(255,255,255,0.1)');
                        grad.addColorStop(1, 'rgba(255,255,255,0.05)');
                        ctx.strokeStyle = grad;

                        ctx.beginPath();
                        ctx.moveTo(n1.x, n1.y);
                        const midX = (n1.x + n2.x) / 2;
                        ctx.bezierCurveTo(midX, n1.y, midX, n2.y, n2.x, n2.y);
                        ctx.stroke();
                    }
                });

                // Draw Packets
                for (let i = state.packets.length - 1; i >= 0; i--) {
                    const p = state.packets[i];
                    p.progress += p.speed;

                    const n1 = state.nodes.find((n: any) => n.id === p.fromId);
                    const n2 = state.nodes.find((n: any) => n.id === p.toId);

                    if (n1 && n2) {
                        const midX = (n1.x + n2.x) / 2;
                        const t = p.progress;
                        const invT = 1 - t;

                        const x = invT*invT*invT*n1.x + 3*invT*invT*t*midX + 3*invT*t*t*midX + t*t*t*n2.x;
                        const y = invT*invT*invT*n1.y + 3*invT*invT*t*n1.y + 3*invT*t*t*n2.y + t*t*t*n2.y;

                        ctx.fillStyle = color;
                        ctx.shadowBlur = 10; ctx.shadowColor = color;
                        ctx.beginPath(); ctx.arc(x, y, 3, 0, Math.PI*2); ctx.fill();
                        ctx.shadowBlur = 0;

                        if (p.progress >= 1) {
                            n2.active = 1.0;
                            const nextLinks = state.links.filter((l: any) => l.from === n2.id);
                            nextLinks.forEach((l: any) => {
                                state.packets.push({ fromId: l.from, toId: l.to, progress: 0, speed: 0.02 });
                            });
                            state.packets.splice(i, 1);
                        }
                    }
                }

                // Draw Nodes
                state.nodes.forEach((n: any) => {
                    const isActive = n.active > 0.01;
                    if (n.active > 0) n.active *= 0.95;

                    ctx.save();
                    ctx.translate(n.x, n.y);

                    if (n.type === 'trigger') {
                        ctx.fillStyle = isActive ? color : '#1a1a1c';
                        ctx.strokeStyle = isActive ? '#fff' : 'rgba(255,255,255,0.2)';
                        ctx.beginPath(); ctx.moveTo(0, -20); ctx.lineTo(20, 0); ctx.lineTo(0, 20); ctx.lineTo(-20, 0); ctx.closePath();
                    } else if (n.type === 'process') {
                        ctx.fillStyle = isActive ? color : '#1a1a1c';
                        ctx.strokeStyle = isActive ? '#fff' : 'rgba(255,255,255,0.2)';
                        drawRoundedRect(-40, -20, 80, 40, 4);
                    } else {
                        ctx.fillStyle = isActive ? color : '#1a1a1c';
                        ctx.strokeStyle = isActive ? '#fff' : 'rgba(255,255,255,0.2)';
                        drawRoundedRect(-30, -15, 60, 30, 15);
                    }

                    ctx.globalAlpha = isActive ? 0.8 : 0.5;
                    ctx.fill();
                    ctx.globalAlpha = 1;
                    ctx.lineWidth = 1;
                    ctx.stroke();

                    ctx.fillStyle = '#fff';
                    ctx.font = '9px monospace';
                    ctx.textAlign = 'center';
                    ctx.textBaseline = 'middle';

                    const textW = ctx.measureText(n.label).width;
                    ctx.fillStyle = 'rgba(0,0,0,0.6)';
                    ctx.fillRect(-textW/2 - 4, 22, textW + 8, 14);
                    ctx.fillStyle = isActive ? color : '#888';
                    ctx.fillText(n.label, 0, 29);

                    ctx.restore();
                });
            }
            else if (mode === 'core') {
                if (Math.random() > 0.96) {
                    state.nodes[0].active = 1; 
                    const startLinks = state.links.filter((l: any) => l.from === 0);
                    if (startLinks.length > 0) {
                        const startLink = startLinks[Math.floor(Math.random() * startLinks.length)];
                        state.particles.push({
                            linkIdx: state.links.indexOf(startLink),
                            t: 0,
                            speed: 0.08
                        });
                    }
                }

                ctx.translate(cx, cy);
                ctx.rotate(time * 0.05);

                ctx.strokeStyle = 'rgba(255,255,255,0.08)';
                ctx.lineWidth = 1;
                ctx.beginPath();
                state.links.forEach((l: any) => {
                    const n1 = state.nodes[l.from];
                    const n2 = state.nodes[l.to];
                    if (n1 && n2) {
                        ctx.moveTo(n1.x, n1.y);
                        ctx.lineTo(n2.x, n2.y);
                    }
                });
                ctx.stroke();

                state.nodes.forEach((n:any) => {
                    if (n.active > 0) {
                        ctx.fillStyle = color;
                        ctx.shadowBlur = 10 * n.active;
                        ctx.shadowColor = color;
                        n.active -= 0.05;
                    } else {
                        ctx.fillStyle = n.layer === 0 ? color : 'rgba(255,255,255,0.3)';
                        ctx.shadowBlur = 0;
                    }
                    const size = n.layer === 0 ? 4 : 2;
                    ctx.beginPath(); ctx.arc(n.x, n.y, size, 0, Math.PI*2); ctx.fill();
                    ctx.shadowBlur = 0;
                });

                for(let i=state.particles.length-1; i>=0; i--) {
                    const p = state.particles[i];
                    p.t += p.speed;
                    const link = state.links[p.linkIdx];
                    if (!link) { state.particles.splice(i,1); continue; }

                    const n1 = state.nodes[link.from];
                    const n2 = state.nodes[link.to];

                    if (n1 && n2) {
                        const currX = n1.x + (n2.x - n1.x) * p.t;
                        const currY = n1.y + (n2.y - n1.y) * p.t;
                        ctx.fillStyle = '#fff';
                        ctx.shadowBlur = 5; ctx.shadowColor = '#fff';
                        ctx.fillRect(currX-1.5, currY-1.5, 3, 3);
                        ctx.shadowBlur = 0;
                        if (p.t >= 1) {
                            n2.active = 1;
                            // Propagate
                            if (n2.layer < 3 && Math.random() > 0.3) {
                                const nextLinks = state.links
                                    .map((l: any, idx: number) => ({...l, idx}))
                                    .filter((l: any) => l.from === link.to);

                                if (nextLinks.length > 0) {
                                    const nextL = nextLinks[Math.floor(Math.random() * nextLinks.length)];
                                    state.particles.push({ linkIdx: nextL.idx, t: 0, speed: 0.08 });
                                }
                            }
                            state.particles.splice(i, 1);
                        }
                    } else {
                        state.particles.splice(i, 1);
                    }
                }
                ctx.rotate(-time * 0.05);
                ctx.translate(-cx, -cy);
            }
            // ... (Other modes: swarm, translation - omitted for brevity as they weren't reported broken, but pattern holds)
            else if (mode === 'swarm') {
                // (Keeping swarm logic intact as it was stable)
                // ... (Swarm logic from original file) ...
                // Re-inserted swarm logic for completeness to avoid regression
                const beltY = h * 0.65; 
                const inputEnd = w * 0.45;
                const outputStart = w * 0.55;
                const agentX = w * 0.5;
                const agentBaseY = beltY + 40;

                const boxSize = 18;
                const speed = 1.0; 
                const animSpeed = 0.03;

                const COLORS = ['#22d3ee', '#a78bfa', '#fbbf24']; 
                const TARGET_YS = [beltY - 80, beltY - 40, beltY];

                const lastBox = state.boxes.length > 0 ? state.boxes[state.boxes.length - 1] : null;
                const safeToSpawn = !lastBox || (lastBox.x > 80); 

                if (safeToSpawn && Math.random() > 0.99) {
                    const typeIdx = Math.floor(Math.random() * 3);
                    state.boxes.push({
                        x: -20,
                        y: beltY - boxSize,
                        w: boxSize,
                        h: boxSize,
                        color: COLORS[typeIdx],
                        targetLane: typeIdx,
                        state: 'conveyor_in' 
                    });
                }

                ctx.fillStyle = 'rgba(255,255,255,0.1)';
                ctx.fillRect(0, beltY, inputEnd, 4);
                TARGET_YS.forEach(y => {
                    ctx.fillRect(outputStart, y + boxSize, w - outputStart, 4);
                });

                ctx.fillStyle = 'rgba(255,255,255,0.2)';
                const dashOffset = (time * 60) % 40; 
                for(let i=0; i<inputEnd; i+=40) {
                    const x = i + dashOffset;
                    if(x < inputEnd) ctx.fillRect(x, beltY, 4, 4);
                }
                TARGET_YS.forEach(y => {
                    for(let i=outputStart; i<w; i+=40) {
                        const x = i + dashOffset; 
                        if(x > outputStart) ctx.fillRect(x, y + boxSize, 4, 4);
                    }
                });

                const agent = state.agent;
                ctx.fillStyle = '#333';
                ctx.fillRect(agentX - 15, agentBaseY - 20, 30, 20); 

                const pivotX = agentX;
                const pivotY = agentBaseY - 20;

                let armX = pivotX;
                let armY = beltY - 60; 
                let grabberGap = 10;

                if (agent.state === 'idle') {
                    const target = state.boxes.find((b: any) => 
                        b.state === 'conveyor_in' && 
                        b.x > inputEnd - 60 && 
                        b.x < inputEnd
                    );
                    if (target) {
                        agent.state = 'reaching';
                        agent.targetBox = target;
                        agent.t = 0;
                    }
                }

                if (agent.state === 'reaching') {
                    agent.t += animSpeed;
                    const t = Math.min(1, agent.t);
                    const b = agent.targetBox;
                    if (b) {
                        if(b.x < inputEnd - 20) b.x += speed;
                        armX = pivotX + (b.x + b.w/2 - pivotX) * t;
                        armY = (pivotY - 80) + (b.y - (pivotY - 80)) * t;
                        if (t >= 1) { agent.state = 'grasping'; agent.t = 0; }
                    } else {
                        agent.state = 'idle'; // Reset if target gone
                    }
                } 
                else if (agent.state === 'grasping') {
                    agent.t += animSpeed * 2;
                    grabberGap = 10 * (1 - Math.min(1, agent.t));
                    if (agent.targetBox) {
                        armX = agent.targetBox.x + agent.targetBox.w/2;
                        armY = agent.targetBox.y;
                    }
                    if (agent.t >= 1) { agent.state = 'moving'; if(agent.targetBox) agent.targetBox.state = 'lifted'; agent.t = 0; }
                }
                else if (agent.state === 'moving') {
                    agent.t += animSpeed;
                    const t = Math.min(1, agent.t);
                    const b = agent.targetBox;
                    if (b) {
                        const targetY = TARGET_YS[b.targetLane];

                        const startX = inputEnd - 20;
                        const targetX = outputStart + 20;

                        armX = startX + (targetX - startX) * t;
                        const midY = Math.min(beltY, targetY) - 60;
                        armY = (1-t)*(1-t)*beltY + 2*(1-t)*t*midY + t*t*targetY;

                        grabberGap = 0;
                        b.x = armX - b.w/2;
                        b.y = armY;

                        if (t >= 1) { agent.state = 'releasing'; agent.t = 0; }
                    }
                }
                else if (agent.state === 'releasing') {
                    agent.t += animSpeed * 2;
                    const b = agent.targetBox;
                    if (b) {
                        armX = b.x + b.w/2;
                        armY = b.y;
                        grabberGap = 10 * Math.min(1, agent.t);

                        if (agent.t >= 1) {
                            b.state = 'conveyor_out';
                            b.y = TARGET_YS[b.targetLane];
                            agent.state = 'returning';
                            agent.targetBox = null;
                            agent.t = 0;
                        }
                    }
                }
                else if (agent.state === 'returning') {
                    agent.t += animSpeed;
                    const t = Math.min(1, agent.t);
                    const startX = outputStart + 20;
                    const startY = armY;
                    const targetX = pivotX;
                    const targetY = beltY - 60;
                    armX = startX + (targetX - startX) * t;
                    armY = startY + (targetY - startY) * t;
                    if (t >= 1) agent.state = 'idle';
                }
                else {
                    armX = pivotX + Math.sin(time * 2) * 5;
                    armY = beltY - 60 + Math.cos(time * 3) * 5;
                }

                ctx.strokeStyle = color;
                ctx.lineWidth = 2;
                ctx.beginPath();
                ctx.moveTo(pivotX, pivotY);
                const elbowX = (pivotX + armX) / 2 - 20; 
                const elbowY = Math.min(pivotY, armY) - 30;
                ctx.quadraticCurveTo(elbowX, elbowY, armX, armY);
                ctx.stroke();

                ctx.fillStyle = '#fff';
                ctx.beginPath(); ctx.arc(pivotX, pivotY, 3, 0, Math.PI*2); ctx.fill();
                ctx.beginPath(); ctx.arc(armX, armY, 3, 0, Math.PI*2); ctx.fill();

                ctx.save();
                ctx.translate(armX, armY);
                ctx.fillStyle = color;
                ctx.fillRect(-8 - grabberGap/2, -5, 4, 15);
                ctx.fillRect(4 + grabberGap/2, -5, 4, 15);
                ctx.restore();

                for (let i = state.boxes.length - 1; i >= 0; i--) {
                    const b = state.boxes[i];
                    if (b.state === 'conveyor_in') {
                        if (agent.targetBox !== b || agent.state === 'reaching') {
                             if (b.x < inputEnd - 20) b.x += speed; 
                        }
                    } else if (b.state === 'conveyor_out') {
                        b.x += speed;
                    }
                    if (b.x > w + 20) { state.boxes.splice(i, 1); continue; }

                    ctx.fillStyle = b.color;
                    ctx.strokeStyle = '#fff';
                    ctx.lineWidth = 1;
                    ctx.fillRect(b.x, b.y, b.w, b.h);
                    ctx.strokeRect(b.x, b.y, b.w, b.h);
                    ctx.fillStyle = 'rgba(0,0,0,0.3)';
                    ctx.fillRect(b.x + 2, b.y + 2, 4, 4);
                }
            } else if (mode === 'translation') {
                // Translation mode logic
                const colWidth = 140; 
                const numCols = 2; 
                const SNIPPETS = ["POST /api/v1/ingest", "{ id: '8f3a' }", "WARN: Latency", "Converting...", "0x4F3E21", "SELECT * FROM logs", "Processing...", "struct Node", "ERROR: Timeout", "> System.init()"];

                if (state.columns.length === 0) {
                    state.columns = Array.from({ length: numCols }, (_, i) => ({
                        x: 20 + i * (colWidth + 10),
                        y: Math.random() * h,
                        speed: 0.5 + Math.random() * 0.5,
                        items: Array.from({ length: 15 }, () => ({
                            text: SNIPPETS[Math.floor(Math.random() * SNIPPETS.length)],
                            y: 0 
                        }))
                    }));
                }

                const gridStartX = w * 0.55;
                const gridCols = 6; const gridRows = 8;
                const cellW = (w * 0.4) / gridCols; const cellH = h / gridRows;
                if (state.grid.length === 0) {
                    for(let i=0; i<gridCols*gridRows; i++) {
                        state.grid.push({
                            x: gridStartX + (i % gridCols) * cellW + cellW/2,
                            y: Math.floor(i / gridCols) * cellH + cellH/2,
                            filled: false, alpha: 0.2
                        });
                    }
                }

                ctx.font = '10px monospace';
                ctx.textAlign = 'left';

                state.columns.forEach((col: any) => {
                    col.y -= col.speed;
                    if (col.y < -300) col.y = h; 

                    col.items.forEach((item: any, i: number) => {
                        const yPos = col.y + i * 20;
                        const drawnY = yPos % (h + 300) - 50;

                        if (drawnY > -20 && drawnY < h + 20) {
                            const isScanned = Math.abs(drawnY - h/2) < 20;
                            ctx.fillStyle = isScanned ? '#fff' : 'rgba(255,255,255,0.3)';
                            if (isScanned) {
                                if (Math.random() > 0.98) {
                                    const empty = state.grid.filter((g: any) => !g.filled);
                                    if (empty.length > 0) {
                                        const t = empty[Math.floor(Math.random() * empty.length)];
                                        t.filled = true;
                                        state.particles.push({
                                            x: col.x + 80, y: drawnY,
                                            tx: t.x, ty: t.y,
                                            progress: 0, speed: 0.05,
                                            target: t
                                        });
                                    }
                                }
                            }
                            ctx.fillText(item.text, col.x, drawnY);
                        }
                    });
                });

                ctx.fillStyle = color;
                ctx.globalAlpha = 0.1;
                ctx.fillRect(0, h/2 - 20, w * 0.45, 40);
                ctx.globalAlpha = 0.8;
                ctx.fillRect(0, h/2, w * 0.45, 1);

                ctx.globalAlpha = 1;
                for (let i = state.particles.length - 1; i >= 0; i--) {
                    const p = state.particles[i];
                    p.progress += p.speed;
                    const t = p.progress;
                    const lx = p.x + (p.tx - p.x) * t;
                    const ly = p.y + (p.ty - p.y) * t;

                    ctx.fillStyle = color;
                    ctx.fillRect(lx - 2, ly - 2, 4, 4);

                    if (p.progress >= 1) {
                        p.target.alpha = 1.0;
                        state.particles.splice(i, 1);
                    }
                }

                state.grid.forEach((cell: any) => {
                    if (cell.filled) cell.alpha = Math.max(0.4, cell.alpha - 0.02);
                    else cell.alpha = 0.1;
                    const s = Math.min(cellW, cellH) * 0.6;
                    ctx.strokeStyle = color; ctx.globalAlpha = cell.alpha; ctx.lineWidth = 1;
                    ctx.strokeRect(cell.x - s/2, cell.y - s/2, s, s);
                    if (cell.filled) {
                        ctx.fillStyle = color; ctx.globalAlpha = cell.alpha * 0.6;
                        ctx.fillRect(cell.x - s/2 + 2, cell.y - s/2 + 2, s - 4, s - 4);
                        if (Math.random() > 0.995) cell.filled = false;
                    }
                });
            }

            ctx.globalAlpha = 1;
            frameId = requestAnimationFrame(render);
        };

        const observer = new ResizeObserver(() => { 
            // Debounce resize to prevent loop error
            window.requestAnimationFrame(() => resize()); 
        });
        observer.observe(container);

        // Initial setup
        resize();
        render();

        return () => {
            observer.disconnect();
            cancelAnimationFrame(frameId);
        };
    }, [mode, color]);

    return (
        <div ref={containerRef} className="w-full h-full relative overflow-hidden bg-[#0c0c0e]">
            <canvas ref={canvasRef} className="block absolute top-0 left-0" />
            <div className="absolute inset-0 pointer-events-none opacity-20" style={{ backgroundImage: 'linear-gradient(rgba(18, 16, 16, 0) 50%, rgba(0, 0, 0, 0.25) 50%), linear-gradient(90deg, rgba(255, 0, 0, 0.06), rgba(0, 255, 0, 0.02), rgba(0, 0, 255, 0.06))', backgroundSize: '100% 2px, 3px 100%' }} />
        </div>
    );
};

