const DistillationVisualizer: React.FC<{ color: string }> = ({ color }) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        let w = canvas.width = 300;
        let h = canvas.height = 300;

        // FIXED ANIMATION: Rising Bubbles instead of static density
        const particles: any[] = [];
        for(let i=0; i<60; i++) {
            particles.push({
                x: Math.random() * w,
                y: Math.random() * h,
                r: Math.random() * 3 + 1,
                speed: 0.5 + Math.random() * 1.5,
                wobble: Math.random() * Math.PI * 2
            });
        }

        let frameId: number;
        const render = () => {
            if (canvas.parentElement) {
                w = canvas.width = canvas.parentElement.clientWidth;
                h = canvas.height = canvas.parentElement.clientHeight;
            }
            ctx.clearRect(0,0,w,h);

            // Draw Tank Lines
            ctx.strokeStyle = 'rgba(255,255,255,0.1)';
            ctx.lineWidth = 2;
            ctx.beginPath();
            ctx.moveTo(w*0.3, 0); ctx.lineTo(w*0.3, h);
            ctx.moveTo(w*0.7, 0); ctx.lineTo(w*0.7, h);
            ctx.stroke();

            // Separation Levels
            [0.2, 0.4, 0.6, 0.8].forEach(lvl => {
                ctx.beginPath(); ctx.moveTo(w*0.3, h*lvl); ctx.lineTo(w*0.7, h*lvl); ctx.stroke();
            });

            particles.forEach(p => {
                // Rising motion
                p.y -= p.speed;
                p.x += Math.sin(p.y * 0.05 + p.wobble) * 0.5;

                // Reset at top
                if (p.y < 0) {
                    p.y = h + 10;
                    p.x = w*0.35 + Math.random() * (w*0.3); // Spawn in tank
                }

                // Constrain to tank
                if(p.x < w*0.32) p.x = w*0.32;
                if(p.x > w*0.68) p.x = w*0.68;

                ctx.fillStyle = color;
                // Opacity based on height (fades at top)
                ctx.globalAlpha = 0.2 + (p.y / h) * 0.6;
                ctx.beginPath(); ctx.arc(p.x, p.y, p.r, 0, Math.PI*2); ctx.fill();
            });
            ctx.globalAlpha = 1;
            frameId = requestAnimationFrame(render);
        };
        render();
        return () => cancelAnimationFrame(frameId);
    }, [color]);
    return <canvas ref={canvasRef} className="w-full h-full" />;
};

const GridSyncVisualizer: React.FC<{ color: string }> = ({ color }) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const mouseRef = useRef({ x: 0, y: 0 });

    useEffect(() => {
        const handleMove = (e: MouseEvent) => {
            if (canvasRef.current) {
                const r = canvasRef.current.getBoundingClientRect();
                mouseRef.current = { x: e.clientX - r.left, y: e.clientY - r.top };
            }
        };
        const el = canvasRef.current;
        if(el) el.addEventListener('mousemove', handleMove);
        return () => { if(el) el.removeEventListener('mousemove', handleMove); }
    }, []);

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        let w = canvas.width = 300;
        let h = canvas.height = 300;

        let t = 0;
        let frameId: number;
        const render = () => {
            if (canvas.parentElement) {
                w = canvas.width = canvas.parentElement.clientWidth;
                h = canvas.height = canvas.parentElement.clientHeight;
            }
            t += 0.05;
            ctx.clearRect(0,0,w,h);

            // Supply Wave (Green)
            ctx.beginPath();
            ctx.strokeStyle = color;
            ctx.lineWidth = 2;
            for(let x=0; x<w; x+=5) {
                const dist = Math.abs(x - mouseRef.current.x);
                const influence = Math.max(0, 1 - dist/100) * 20;
                const y = h/2 + Math.sin(x * 0.03 + t) * 40 + influence;
                if(x===0) ctx.moveTo(x,y); else ctx.lineTo(x,y);
            }
            ctx.stroke();

            // Demand Wave (White - softened opacity)
            ctx.beginPath();
            ctx.strokeStyle = 'rgba(255,255,255,0.15)'; // Softer white
            for(let x=0; x<w; x+=5) {
                const dist = Math.abs(x - mouseRef.current.x);
                const influence = Math.max(0, 1 - dist/100) * 20;
                // Slight phase offset
                const y = h/2 + Math.sin(x * 0.03 + t + 0.5) * 40 - influence; 
                if(x===0) ctx.moveTo(x,y); else ctx.lineTo(x,y);
            }
            ctx.stroke();

            // Sync nodes
            if (Math.sin(t) > 0.9) {
                ctx.fillStyle = '#fff';
                ctx.beginPath(); ctx.arc(w/2, h/2 + 40, 3, 0, Math.PI*2); ctx.fill();
                ctx.beginPath(); ctx.arc(w/2, h/2 - 40, 3, 0, Math.PI*2); ctx.fill();
            }

            frameId = requestAnimationFrame(render);
        };
        render();
        return () => cancelAnimationFrame(frameId);
    }, [color]);
    return <canvas ref={canvasRef} className="w-full h-full" />;
};

const GeologicalScanVisualizer: React.FC<{ color: string }> = ({ color }) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        let w = canvas.width = 300;
        let h = canvas.height = 300;

        let t = 0;
        let frameId: number;

        // Ore Deposits
        const ores = Array.from({length: 10}, () => ({
            x: Math.random() * 300,
            y: 50 + Math.random() * 250,
            val: Math.random()
        }));

        // Strata Layers
        const layers = [
            { y: 50, color: '#222' },
            { y: 120, color: '#1a1a1a' },
            { y: 200, color: '#111' },
            { y: 280, color: '#050505' }
        ];

        const render = () => {
            if (canvas.parentElement) {
                w = canvas.width = canvas.parentElement.clientWidth;
                h = canvas.height = canvas.parentElement.clientHeight;
            }
            t += 2;
            ctx.clearRect(0,0,w,h);

            // Draw Layers
            layers.forEach(l => {
                ctx.fillStyle = l.color;
                ctx.fillRect(0, l.y, w, 80);
            });

            // Draw Ores (Hidden mostly)
            ores.forEach(o => {
                ctx.fillStyle = 'rgba(255, 255, 255, 0.05)';
                ctx.beginPath(); ctx.arc(o.x, o.y, 3, 0, Math.PI*2); ctx.fill();
            });

            // Borehole
            const bx = w/2 - 20;
            ctx.fillStyle = 'rgba(0,0,0,0.5)';
            ctx.fillRect(bx, 0, 40, h);
            ctx.strokeStyle = color;
            ctx.lineWidth = 1;
            ctx.strokeRect(bx, 0, 40, h);

            // Scan Line
            const scanY = t % h;
            ctx.fillStyle = color;
            ctx.shadowBlur = 15; ctx.shadowColor = color;
            ctx.fillRect(bx - 10, scanY, 60, 2);
            ctx.shadowBlur = 0;

            // Highlight Ores when scanned
            ores.forEach(o => {
                if (Math.abs(o.y - scanY) < 20 && Math.abs(o.x - w/2) < 50) {
                    ctx.fillStyle = '#fff';
                    ctx.shadowBlur = 10; ctx.shadowColor = '#fff';
                    ctx.beginPath(); ctx.arc(o.x, o.y, 5, 0, Math.PI*2); ctx.fill();
                    ctx.shadowBlur = 0;

                    // Connection line
                    ctx.strokeStyle = 'rgba(255,255,255,0.2)';
                    ctx.beginPath(); ctx.moveTo(w/2, scanY); ctx.lineTo(o.x, o.y); ctx.stroke();
                }
            });

            frameId = requestAnimationFrame(render);
        };
        render();
        return () => cancelAnimationFrame(frameId);
    }, [color]);
    return <canvas ref={canvasRef} className="w-full h-full" />;
};

const WaterVisualizer: React.FC<{ color: string }> = ({ color }) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        let w = canvas.width = 300;
        let h = canvas.height = 300;

        const particles: any[] = [];
        for(let i=0; i<50; i++) particles.push({ x: Math.random()*w, y: Math.random()*h, speed: 1+Math.random() });

        let frameId: number;
        const render = () => {
            if (canvas.parentElement) {
                w = canvas.width = canvas.parentElement.clientWidth;
                h = canvas.height = canvas.parentElement.clientHeight;
            }
            ctx.clearRect(0,0,w,h);

            // Filter Barrier
            ctx.fillStyle = 'rgba(255,255,255,0.1)';
            ctx.fillRect(w/2 - 2, 0, 4, h);

            particles.forEach(p => {
                p.x += p.speed;
                if (p.x > w) p.x = 0;

                // Change color after filter
                if (p.x > w/2) {
                    ctx.fillStyle = color; // Pure
                    ctx.globalAlpha = 0.8;
                } else {
                    ctx.fillStyle = '#555'; // Dirty
                    ctx.globalAlpha = 0.4;
                }

                ctx.beginPath(); ctx.arc(p.x, p.y, 2, 0, Math.PI*2); ctx.fill();
            });
            ctx.globalAlpha = 1;
            frameId = requestAnimationFrame(render);
        };
        render();
        return () => cancelAnimationFrame(frameId);
    }, [color]);
    return <canvas ref={canvasRef} className="w-full h-full" />;
};

// --- BACKGROUND FOR MODAL ---
const ResourceBackground: React.FC<{ mode: string, color: string }> = ({ mode, color }) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        let w = canvas.width = window.innerWidth;
        let h = canvas.height = window.innerHeight;
        let time = 0;
        let frameId: number;

        // MODE 1: DISTILLATION (Bubbles)
        const bubbles = Array.from({length: 50}, () => ({
            x: Math.random() * w, y: Math.random() * h,
            r: Math.random() * 20 + 5,
            speed: Math.random() * 2 + 0.5
        }));

        const render = () => {
            time += 0.01;
            ctx.fillStyle = 'rgba(2,2,2,0.2)';
            ctx.fillRect(0,0,w,h);

            if (mode === 'distillation') {
                bubbles.forEach(b => {
                    b.y -= b.speed;
                    if (b.y < -50) b.y = h + 50;
                    ctx.fillStyle = color;
                    ctx.globalAlpha = 0.1 + (b.r / 30);
                    ctx.beginPath(); ctx.arc(b.x, b.y, b.r, 0, Math.PI*2); ctx.fill();
                });
            } 
            else if (mode === 'grid') {
                ctx.strokeStyle = color;
                ctx.lineWidth = 1;
                ctx.globalAlpha = 0.2;

                // Perspective Grid
                const lines = 20;

                for(let i=0; i<lines; i++) {
                    const offset = (time * 100 + i * 100) % (h);
                    const y = (h/2) + offset; // Below horizon
                    ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(w, y); ctx.stroke();

                    const x = (time * 50 + i * (w/lines)) % w;
                    ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, h); ctx.stroke();
                }
            } 
            else if (mode === 'lidar') {
                const scanX = (time * 200) % w;
                ctx.fillStyle = color;
                ctx.globalAlpha = 0.1;
                ctx.fillRect(scanX, 0, 50, h);

                // Random points
                for(let i=0; i<20; i++) {
                    const rx = Math.random() * w;
                    const ry = Math.random() * h;
                    if (Math.abs(rx - scanX) < 100) {
                        ctx.globalAlpha = 0.8;
                        ctx.fillRect(rx, ry, 2, 2);
                    }
                }
            }
            else if (mode === 'filter') {
                ctx.fillStyle = color;
                for(let i=0; i<w; i+=20) {
                    const y = h/2 + Math.sin(i * 0.01 + time) * 50;
                    ctx.globalAlpha = 0.1;
                    ctx.fillRect(i, y, 10, h);
                }
            }

            ctx.globalAlpha = 1;
            frameId = requestAnimationFrame(render);
        };
        render();

        const resize = () => { 
            w = canvas.width = window.innerWidth; 
            h = canvas.height = window.innerHeight; 
        };
        window.addEventListener('resize', resize);
        return () => { window.removeEventListener('resize', resize); cancelAnimationFrame(frameId); };
    }, [mode, color]);

    return <canvas ref={canvasRef} className="absolute inset-0 w-full h-full opacity-30" />;
};

