            for(let i=0; i<5; i++) { const px = (time * 100 + i * 200) % (w+100) - 50; const py = h/2 + Math.sin(time + i)*50; ctx.fillStyle = '#fff'; ctx.shadowBlur = 10; ctx.shadowColor = '#fff'; ctx.fillRect(px, py, 4, 4); ctx.shadowBlur = 0; }
