                                                <>
                                                    Get In Touch 
                                                    <ArrowRight size={16} className="group-hover/btn:translate-x-1 transition-transform" />
                                                </>
                                            )}
                                        </span>
                                    </button>
                                </form>
                            )}
                        </div>
                    </div>
                </div>
            </section>

            <SiteFooter />

        </div>
    );
};

import React, { useState } from 'react';
import { Check, Loader2 } from 'lucide-react';

interface RecaptchaProps {
    onChange: (token: string | null) => void;
    theme?: 'light' | 'dark';
}

export const Recaptcha: React.FC<RecaptchaProps> = ({ onChange, theme = 'dark' }) => {
    const [status, setStatus] = useState<'idle' | 'verifying' | 'verified'>('idle');

    const handleClick = () => {
        if (status !== 'idle') return;

        setStatus('verifying');
        setTimeout(() => {
            setStatus('verified');
            // Provide a fake token to allow form submission
            onChange("mock_token_verified_123");
        }, 1200); // Fake network delay
    };

    const isDark = theme === 'dark';

    return (
        <div 
            onClick={handleClick}
            className={`
                my-4 inline-flex items-center p-3 rounded-md border shadow-sm cursor-pointer select-none transition-colors min-w-[240px]
                ${isDark ? 'bg-[#222] border-[#555] hover:bg-[#2a2a2a]' : 'bg-[#f9f9f9] border-[#d3d3d3] hover:bg-[#f0f0f0]'}
            `}
        >
            <div className={`
                w-6 h-6 rounded-[2px] border mr-3 flex items-center justify-center bg-white transition-all
                ${isDark ? 'border-[#c1c1c1]' : 'border-[#c1c1c1]'}
            `}>
                {status === 'verifying' && <Loader2 className="w-4 h-4 text-blue-500 animate-spin" />}
                {status === 'verified' && <Check className="w-5 h-5 text-green-500" strokeWidth={3} />}
            </div>

            <span className={`text-sm font-sans mr-auto ${isDark ? 'text-[#e0e0e0]' : 'text-[#333]'}`}>
                I'm not a robot
            </span>

            <div className="flex flex-col items-center justify-center pl-2 ml-2 border-l border-opacity-10 border-gray-500">
                <img 
                    src="https://www.gstatic.com/recaptcha/api2/logo_48.png" 
                    alt="reCAPTCHA" 
                    className="w-5 h-5 mb-0.5 opacity-70"
                />
                <span className={`text-[8px] leading-none ${isDark ? 'text-[#aaa]' : 'text-[#555]'}`}>reCAPTCHA</span>
                <div className={`text-[8px] leading-none mt-0.5 ${isDark ? 'text-[#aaa]' : 'text-[#555]'}`}>
                    Privacy - Terms
                </div>
            </div>
        </div>
    );
};
